window.LGS_BANK = window.LGS_BANK || {};
(window.LGS_BANK["ucgenler"] = window.LGS_BANK["ucgenler"] || []).push(
{
  id: "mat-uc-226",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 2,
  soru: "Bir çocuk parkında yerden 2,0 m yükseklikteki bir platformdan zemine inen düz bir kaydırağın boyu 2,9 m'dir. Platform zemine diktir (şekil ölçekli değildir).\n**Platformun tam altındaki zemin noktası ile kaydırağın alt ucu arasındaki uzaklık kaç metredir?**",
  gorsel: "<svg viewBox=\"0 0 300 240\" role=\"img\"><line x1=\"80\" y1=\"50\" x2=\"80\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"80\" y1=\"200\" x2=\"237\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"80\" y1=\"50\" x2=\"237\" y2=\"200\" stroke=\"var(--vurgu)\" stroke-width=\"3\"/><line x1=\"58\" y1=\"50\" x2=\"102\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"5\"/><polyline points=\"80,188 92,188 92,200\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"70\" y=\"130\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">2,0 m</text><text x=\"180\" y=\"112\" text-anchor=\"start\" font-size=\"15\" fill=\"var(--vurgu)\">2,9 m</text><text x=\"158\" y=\"224\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--vurgu)\" font-weight=\"bold\">?</text></svg>",
  secenekler: ["4,9","4,41","2,1","0,9"],
  dogru: 2,
  hatalar: ["Toplama yaptın (2,9 + 2,0 = 4,9). Hipotenüsü bilinen üçgende öbür dik kenar, kareler çıkarılarak bulunur.","Karekök almayı unuttun: 2,9^{2} − 2,0^{2} = 8,41 − 4 = 4,41 sayısı, uzaklığın karesidir.",null,"Boyları doğrudan çıkardın (2,9 − 2,0 = 0,9). Dik üçgende kenarlar değil, kenarların kareleri çıkarılır."],
  aciklama: "Platform, zemin ve kaydırak bir dik üçgen oluşturur. Kaydırak, dik açının karşısındaki en uzun kenar olan hipotenüstür. Pisagor bağıntısı: dik kenarların kareleri toplamı hipotenüsün karesine eşittir.\nAdım 1: Zemindeki uzaklığa d dersek d^{2} + 2,0^{2} = 2,9^{2} olur.\nAdım 2: d^{2} = 8,41 − 4 = 4,41 bulunur.\nAdım 3: 2,1 · 2,1 = 4,41 olduğundan d = 2,1 m'dir.\nSağlama: 2,1^{2} + 2,0^{2} = 4,41 + 4 = 8,41 = 2,9^{2}.\nCevap C."
},
{
  id: "mat-uc-227",
  kazanim: "M.8.3.1.3",
  kademe: 2,
  zorluk: 2,
  soru: "Bir bahçenin A, B ve C köşelerine dikilen üç direk arasındaki uzaklıklar şekilde verilmiştir: |AB| = 12 m, |BC| = 7 m ve |CA| = 9 m.\n**Bu üçgenin köşelerindeki açıların ölçüleri arasındaki doğru sıralama aşağıdakilerden hangisidir?**",
  gorsel: "<svg viewBox=\"0 0 340 245\" role=\"img\"><polygon points=\"40,200 304,200 201.3,85.2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"23.6\" y=\"209.4\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"320.2\" y=\"210.1\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"205.5\" y=\"73.7\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text><text x=\"167\" y=\"224.4\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">12 m</text><text x=\"272\" y=\"142.4\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">7 m</text><text x=\"101.6\" y=\"141.6\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">9 m</text></svg>",
  secenekler: ["m(A) < m(B) < m(C)","m(B) < m(A) < m(C)","m(C) < m(B) < m(A)","m(A) < m(C) < m(B)"],
  dogru: 0,
  hatalar: [null,"[BC] kenarını B köşesiyle eşleştirdin; oysa [BC]'nin karşısında A açısı vardır. Kenar, uçlarındaki köşeyle değil karşısındaki köşeyle eşlenir.","Sıralamayı ters kurdun: büyük kenarın karşısında büyük açı, küçük kenarın karşısında küçük açı bulunur.","[CA] ve [AB] kenarlarını karşılarındaki açıyla değil, uçlarındaki köşeyle eşleştirdin: [CA]'nın karşısında B, [AB]'nin karşısında C vardır."],
  aciklama: "Üçgende büyük kenarın karşısında büyük açı, küçük kenarın karşısında küçük açı bulunur.\nAdım 1: Her kenarı karşısındaki açıyla eşle: [BC] = 7 m kenarının karşısında A, [CA] = 9 m kenarının karşısında B, [AB] = 12 m kenarının karşısında C vardır.\nAdım 2: Kenarları küçükten büyüğe sırala: 7 < 9 < 12.\nAdım 3: Karşılarındaki açıları aynı sırayla yaz: m(A) < m(B) < m(C).\nSık yapılan hata: Kenarı, uçlarındaki köşenin açısıyla eşlemek. Önce kenarın karşısındaki köşeyi bul.\nCevap A."
},
{
  id: "mat-uc-228",
  kazanim: "M.8.3.1.1",
  kademe: 2,
  zorluk: 2,
  soru: "Şekildeki ABC dik üçgeninde m(ABC) = 90°, |AB| = 6 cm, |BC| = 8 cm ve |AC| = 10 cm'dir. C köşesinden [AB] kenarına (gerekirse uzantısına) bir yükseklik çizilecektir.\n**Bu yüksekliğin uzunluğu kaç santimetredir?**",
  gorsel: "<svg viewBox=\"0 0 300 235\" role=\"img\"><polygon points=\"70,70 70,190 230,190\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polyline points=\"70,178 82,178 82,190\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"60\" y=\"135\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">6 cm</text><text x=\"150\" y=\"214\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">8 cm</text><text x=\"176\" y=\"118\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">10 cm</text><text x=\"70\" y=\"58\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"56\" y=\"206\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"244\" y=\"208\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text></svg>",
  secenekler: ["10","8","6","4,8"],
  dogru: 1,
  hatalar: ["Hipotenüsü yükseklik sandın; hipotenüs dik açının karşısındaki kenardır, C'den [AB]'ye inen dikme değildir.",null,"[AB] kenarının uzunluğunu yazdın; [AB], yüksekliğin indiği kenardır. Yükseklik C köşesinden bu kenara inen dikmedir.","Hipotenüse inen yüksekliği hesapladın (6 · 8 ÷ 10 = 4,8). Soruda yükseklik [AB] kenarına inmektedir."],
  aciklama: "Yükseklik, bir köşeden karşı kenara (gerekirse uzantısına) inen dikmedir; kenarla 90° yapar.\nAdım 1: C köşesinden [AB]'ye inen dikmeyi düşün. [BC] kenarı zaten [AB]'ye diktir (m(ABC) = 90°).\nAdım 2: Yani dikmenin ayağı B noktasıdır ve yükseklik [BC] kenarının kendisidir. Dik üçgende dik kenarlar birbirine yüksekliktir.\nAdım 3: Yüksekliğin uzunluğu |BC| = 8 cm'dir.\nSık yapılan hata: Hipotenüse inen yüksekliği (4,8 cm) hesaplamak. Önce yüksekliğin hangi kenara indiğine bak.\nCevap B."
},
{
  id: "mat-uc-229",
  kazanim: "M.8.3.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Özge, bahçesindeki çiçek yatağını üçgen biçiminde bir çitle çevirecektir. Yatağın iki kenarı 5 m ve 9 m, üçüncü kenarı ise tam sayı metredir.\n**Buna göre çitin uzunluğu (üçgenin çevresi) en az kaç metre olabilir?**",
  gorsel: null,
  secenekler: ["18","19","27","28"],
  dogru: 1,
  hatalar: ["Alt sınır olan 4'ü de kabul ettin. 4 + 5 = 9 olduğundan 4, 5, 9 uzunluklu çubuklar bir doğruya yatar, üçgen oluşmaz.",null,"En küçük değer yerine üçüncü kenarın en büyük tam sayı değerini (13) alıp 14 + 13 = 27 buldun.","Üst sınır olan 14'ü kabul ettin (14 + 14 = 28). 5 + 9 = 14 olduğundan eşitlik durumunda üçgen oluşmaz."],
  aciklama: "Üçgende bir kenar, diğer iki kenarın toplamından küçük, farkından büyüktür: |a − b| < c < a + b.\nAdım 1: Üçüncü kenara x dersek 9 − 5 < x < 9 + 5, yani 4 < x < 14 olur.\nAdım 2: Çevre en az olsun diye x'in en küçük tam sayı değeri alınır: x = 5.\nAdım 3: Çevre = 5 + 9 + 5 = 19 m'dir.\nSağlama: 5, 9, 5 için 5 + 5 > 9 ve 9 − 5 < 5 olduğundan üçgen oluşur.\nCevap B."
},
{
  id: "mat-uc-230",
  kazanim: "M.8.3.1.4",
  kademe: 2,
  zorluk: 2,
  soru: "Teknik resim dersinde Aras, KLM üçgenini çizecektir. Öğretmeni ona |KL| = 9 cm ve m(LKM) = 110° ölçülerini vermiş, üçüncü ölçü olarak m(KLM) açısının değerini Aras'ın seçmesini istemiştir.\n**Aşağıdaki değerlerden hangisi seçilirse bu ölçülerle üçgen __çizilemez__?**",
  gorsel: null,
  secenekler: ["40°","55°","65°","70°"],
  dogru: 3,
  hatalar: ["Bu seçimde iki açının toplamı 110° + 40° = 150° olur. 180°'den küçük olduğu için ışınlar kesişir ve üçgen çizilir.","Bu seçimde iki açının toplamı 110° + 55° = 165° olur. 180°'den küçük olduğu için üçgen çizilebilir (üçüncü açı 15° olur).","Bu seçimde iki açının toplamı 110° + 65° = 175° olur. Küçük de olsa 180°'den azdır; ışınlar uzakta kesişir ve üçgen çizilebilir.",null],
  aciklama: "Bir kenar ve ona komşu iki açı verilen üçgen çizilirken, komşu açıların toplamı 180°'den küçük olmalıdır; aksi hâlde kenarın uçlarından çizilen ışınlar kesişmez.\nAdım 1: [KL] kenarına komşu açılar m(K) = 110° ve m(L)'dir.\nAdım 2: Toplam 180°'den küçük olmalıdır: 110° + m(L) < 180° ise m(L) < 70° gerekir.\nAdım 3: 70° seçilirse toplam tam 180° olur; ışınlar birbirine paralel gider, kesişmez ve üçgen çizilemez.\nSağlama: 40°, 55° ve 65° değerleri 70°'den küçüktür, bunlarla üçgen çizilir.\nCevap D."
},
{
  id: "mat-uc-231",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 2,
  soru: "Bir okulun bahçesindeki bayrak direği zemine dik biçimde dikilidir. Direğin tepesine bağlanan gergi telinin boyu 20 m'dir ve telin zemindeki ucu direğin dibinden 12 m uzağa çakılmıştır (tel gergin ve doğrusaldır).\n**Bayrak direğinin boyu kaç metredir?**",
  gorsel: "<svg viewBox=\"0 0 270 250\" role=\"img\"><polygon points=\"70,50 70,210 190,210\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polyline points=\"70,198 82,198 82,210\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"130\" y=\"233\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">12 m</text><text x=\"60\" y=\"135\" text-anchor=\"end\" font-size=\"15\" fill=\"var(--vurgu)\" font-weight=\"bold\">?</text><text x=\"156\" y=\"124\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">20 m</text></svg>",
  secenekler: ["16","20","32","256"],
  dogru: 0,
  hatalar: [null,"Telin boyunu direğin boyu sandın. Tel hipotenüstür; dik kenar olan direkten her zaman uzundur.","Toplama yaptın (20 + 12 = 32). Hipotenüsü bilinen üçgende öbür dik kenar, kareler çıkarılarak bulunur.","Karekök almayı unuttun: 20^{2} − 12^{2} = 400 − 144 = 256 sayısı direğin boyunun karesidir."],
  aciklama: "Direk, zemin ve tel bir dik üçgen oluşturur; tel hipotenüstür (dik açının karşısındaki en uzun kenar).\nAdım 1: Direğin boyuna h dersek 12^{2} + h^{2} = 20^{2} yazılır.\nAdım 2: h^{2} = 400 − 144 = 256 bulunur.\nAdım 3: 16 · 16 = 256 olduğundan h = 16 m'dir.\nSağlama: 12^{2} + 16^{2} = 144 + 256 = 400 = 20^{2}. (12-16-20, 3-4-5 üçlüsünün 4 katıdır.)\nCevap A."
},
{
  id: "mat-uc-232",
  kazanim: "M.8.3.1.3",
  kademe: 2,
  zorluk: 2,
  soru: "ABC üçgeninde m(A) + m(B) = 110° ve m(B) + m(C) = 130°'dir.\n**Bu üçgenin kenar uzunlukları arasındaki sıralama aşağıdakilerden hangisidir?**",
  gorsel: null,
  secenekler: ["|AB| < |BC| < |CA|","|BC| < |AB| < |CA|","|AB| < |CA| < |BC|","|BC| < |CA| < |AB|"],
  dogru: 3,
  hatalar: ["Açıları kendi harfleriyle başlayan kenarlarla eşledin (A için [AB], B için [BC], C için [CA]). Kenar, karşısındaki köşenin açısıyla eşlenir.","Yalnızca [BC]'yi doğru eşledin. B açısının karşısında [CA], C açısının karşısında [AB] bulunur.","Sıralamayı ters kurdun: küçük açının karşısında küçük kenar, büyük açının karşısında büyük kenar bulunur.",null],
  aciklama: "Üçgenin iç açıları toplamı 180°'dir; büyük açının karşısında büyük kenar bulunur.\nAdım 1: m(A) + m(B) = 110° ise m(C) = 180° − 110° = 70° olur.\nAdım 2: m(B) + m(C) = 130° ise m(A) = 180° − 130° = 50° olur. Buradan m(B) = 180° − 50° − 70° = 60° çıkar.\nAdım 3: Açıların karşısındaki kenarlar: A ↔ [BC], B ↔ [CA], C ↔ [AB]. 50° < 60° < 70° olduğundan |BC| < |CA| < |AB| olur.\nSağlama: 50° + 60° + 70° = 180°, 50° + 60° = 110° ve 60° + 70° = 130°.\nCevap D."
},
{
  id: "mat-uc-233",
  kazanim: "M.8.3.1.1",
  kademe: 2,
  zorluk: 2,
  soru: "Şekildeki ABC üçgeninde [AD], A açısının açıortayıdır (D noktası [BC] üzerindedir). m(BAC) = 84° ve m(ABC) = 50°'dir.\n**m(ADC) kaç derecedir?**",
  gorsel: "<svg viewBox=\"0 0 340 240\" role=\"img\"><polygon points=\"160.5,50.4 35,200 305,200\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"160.5\" y1=\"50.4\" x2=\"165.8\" y2=\"200\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/><path d=\"M 143.8 70.3 A 26 26 0 0 0 161.4 76.4\" fill=\"none\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><path d=\"M 161.7 84.4 A 34 34 0 0 0 184.1 74.9\" fill=\"none\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><text x=\"160.5\" y=\"40.4\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">84°</text><text x=\"97\" y=\"190\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">50°</text><text x=\"138.5\" y=\"20.4\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"23\" y=\"218\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"317\" y=\"218\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text><text x=\"165.8\" y=\"224\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">D</text></svg>",
  secenekler: ["134","96","92","88"],
  dogru: 2,
  hatalar: ["Açıortayın A açısını ikiye böldüğünü kullanmadın; 84° + 50° = 134° yazdın.","180° − 84° = 96° yazdın. Açıortay, A açısını 42° + 42° olarak ikiye böler; ADC açısı ABD üçgeninin dış açısıdır.",null,"ABD üçgeninde m(ADB) = 180° − (42° + 50°) = 88° buldun. Sorulan ADC açısı, ADB ile doğrusal çift olduğundan 180° − 88° = 92°'dir."],
  aciklama: "Açıortay, köşedeki açıyı iki eş açıya ayırır.\nAdım 1: [AD] açıortay olduğundan m(BAD) = m(DAC) = 84° ÷ 2 = 42° olur.\nAdım 2: ABD üçgeninde m(ADB) = 180° − 50° − 42° = 88° bulunur.\nAdım 3: D, [BC] üzerinde olduğundan ADB ile ADC komşu bütünler açılardır: m(ADC) = 180° − 88° = 92°.\nSağlama: ADC üçgeninde m(C) = 180° − 84° − 50° = 46° ve 42° + 92° + 46° = 180°.\nCevap C."
},
{
  id: "mat-uc-234",
  kazanim: "M.8.3.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Bir ressam, kenar uzunlukları 8 cm, 8 cm ve x cm olan üçgen biçimli bir çerçeve yapacaktır. x, santimetre cinsinden bir tam sayıdır.\n**Buna göre x kaç farklı değer alabilir?**",
  gorsel: null,
  secenekler: ["14","15","16","17"],
  dogru: 1,
  hatalar: ["Bir değeri eksik saydın. 1'den 15'e kadar 15 tam sayı vardır; x = 8 de uygundur (üçgen eşkenar olur).",null,"Üst sınır olan 16'yı da kabul ettin. x = 16 olursa 8 + 8 = 16 olur ve çubuklar bir doğruya yatar, üçgen oluşmaz.","Hem 0'ı hem 16'yı saydın. Bir kenar 0 olamaz ve 16 da üçgen oluşturmaz."],
  aciklama: "Üçgen eşitsizliğine göre üçüncü kenar, diğer ikisinin farkından büyük, toplamından küçüktür.\nAdım 1: Kenarlar 8 ve 8 olduğundan farkları 8 − 8 = 0, toplamları 8 + 8 = 16'dır.\nAdım 2: 0 < x < 16 olur.\nAdım 3: Bu aralıktaki tam sayılar 1, 2, 3, …, 15'tir; yani 15 değer vardır.\nSık yapılan hata: Sınırları (0 ve 16) sayıma katmak. Eşitlik durumunda üçgen oluşmaz.\nCevap B."
},
{
  id: "mat-uc-235",
  kazanim: "M.8.3.1.4",
  kademe: 2,
  zorluk: 2,
  soru: "Üçgen çizimi ile ilgili dört arkadaş aşağıdaki cümleleri söylemiştir.\n**Bu cümlelerden hangisi doğrudur?**",
  gorsel: null,
  secenekler: ["Üç açısının ölçüsü bilinen bir üçgen, kenar uzunluklarını bilmeden de her zaman tek türlü çizilir.","Yalnızca iki kenarının uzunluğu bilinen bir üçgen, açı ölçüsü bilinmeden her zaman tek türlü çizilir.","İki kenarının uzunluğu ve aralarındaki açının ölçüsü bilinen bir üçgen her zaman tek türlü çizilir.","Üç kenarının uzunluğu bilinen bir üçgen, uzunluklar nasıl olursa olsun her zaman çizilebilir."],
  dogru: 2,
  hatalar: ["Üç açı verilince açılar aynı kalır ama kenarlar istenildiği kadar büyütülebilir; sonsuz çok üçgen çizilebilir.","İki kenar verilince üçüncü kenar ve açılar değişebilir; arada kalan açı da bilinmelidir.",null,"Üçgen eşitsizliği sağlanmıyorsa (örneğin 3, 4, 9) kenarlar bir üçgen oluşturamaz."],
  aciklama: "Bir üçgenin tek türlü çizilebilmesi için yeterli bilgi gerekir. Yeterli olanlar: üç kenar, iki kenar ve aralarındaki açı, bir kenar ve ona komşu iki açı.\nAdım 1: Üç açı yetmez; açılar aynı kalırken kenarlar büyüyüp küçülebilir.\nAdım 2: Yalnızca iki kenar yetmez; aradaki açı bilinmezse üçüncü kenar belirsizdir.\nAdım 3: Üç kenar yeterlidir ama kenarlar üçgen eşitsizliğini sağlamalıdır; her uzunluk üçlüsü üçgen vermez.\nAdım 4: İki kenar ve aralarındaki açı verilince üçüncü köşe tek noktaya düşer, üçgen tek türlü çizilir.\nSık yapılan hata: Üç açıyı yeterli saymak.\nCevap C."
},
{
  id: "mat-uc-236",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 2,
  soru: "Dikdörtgen biçimli bir ahşap pano çerçevesinin kısa kenarı 0,8 m, uzun kenarı 1,5 m'dir. Çerçeveyi sağlamlaştırmak için bir köşesinden karşı köşesine düz bir çıta gerilecektir.\n**Çıta kaç metre uzunluğunda olmalıdır?**",
  gorsel: "<svg viewBox=\"0 0 340 205\" role=\"img\"><polygon points=\"70,40 310,40 310,168 70,168\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"70\" y1=\"168\" x2=\"310\" y2=\"40\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"7 4\"/><text x=\"190\" y=\"28\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">1,5 m</text><text x=\"62\" y=\"108\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">0,8 m</text><text x=\"196\" y=\"82\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--vurgu)\" font-weight=\"bold\">?</text></svg>",
  secenekler: ["2,89","2,3","1,7","0,7"],
  dogru: 2,
  hatalar: ["Karekök almayı unuttun: 0,8^{2} + 1,5^{2} = 0,64 + 2,25 = 2,89 sayısı çıtanın boyunun karesidir.","Kenarları topladın (0,8 + 1,5 = 2,3). Köşegen, iki kenarın toplamından kısadır; Pisagor gerekir.",null,"Kenarların farkını aldın (1,5 − 0,8 = 0,7). Köşegen farkla değil, karelerin toplamının kareköküyle bulunur."],
  aciklama: "Köşegen, dikdörtgeni iki dik üçgene ayırır; çıta bu dik üçgenin hipotenüsüdür.\nAdım 1: Çıtanın boyuna c dersek c^{2} = 0,8^{2} + 1,5^{2} olur.\nAdım 2: c^{2} = 0,64 + 2,25 = 2,89 bulunur.\nAdım 3: 1,7 · 1,7 = 2,89 olduğundan c = 1,7 m'dir.\nSağlama: Köşegen 0,8 + 1,5 = 2,3 m'den kısa, 1,5 m'den uzundur; 1,7 m bu aralıktadır.\nCevap C."
},
{
  id: "mat-uc-237",
  kazanim: "M.8.3.1.3",
  kademe: 2,
  zorluk: 2,
  soru: "Aşağıdaki tabloda, ikizkenar üçgen biçiminde kesilmiş dört kâğıdın tepe açıları verilmiştir (tepe açısı, eşit kenarların arasındaki açıdır).\n**Hangi kâğıdın tabanı, eşit kenarlarından birinden __kısadır__?**",
  gorsel: "<table class=\"tablo\"><tr><th>Kâğıt</th><th>Tepe açısı</th></tr><tr><td>L</td><td>60°</td></tr><tr><td>N</td><td>108°</td></tr><tr><td>K</td><td>36°</td></tr><tr><td>M</td><td>84°</td></tr></table>",
  secenekler: ["K kâğıdı","L kâğıdı","M kâğıdı","N kâğıdı"],
  dogru: 0,
  hatalar: [null,"Tepe açısı 60° ise taban açıları da 60° olur; üçgen eşkenardır ve taban kollara eşittir, onlardan kısa değildir.","Tepe açısı 84° ise taban açıları 48°'dir. Tepe açısı daha büyük olduğundan karşısındaki taban kollardan uzundur.","Tepe açısı 108° ise taban açıları 36°'dir. Tepe açısı en büyük açı olduğundan karşısındaki taban en uzun kenardır."],
  aciklama: "İkizkenar üçgende taban açıları eşittir; tabanın karşısında tepe açısı, kolların karşısında taban açıları bulunur. Büyük açının karşısında büyük kenar vardır.\nAdım 1: Her kâğıtta taban açısı = (180° − tepe açısı) ÷ 2 olur: K için 72°, L için 60°, M için 48°, N için 36°.\nAdım 2: Taban, tepe açısının karşısındadır. Taban kollardan kısa olsun diye tepe açısı taban açısından küçük olmalıdır.\nAdım 3: Yalnızca K'da 36° < 72° vardır. Böylece K kâğıdının tabanı kollardan kısadır.\nSağlama: L'de açılar eşit (eşkenar), M ve N'de tepe açısı taban açılarından büyük olduğundan taban uzundur.\nCevap A."
},
{
  id: "mat-uc-238",
  kazanim: "M.8.3.1.1",
  kademe: 2,
  zorluk: 2,
  soru: "Şekildeki ABC üçgeninin A köşesindeki açı geniş açıdır: m(BAC) = 120°. Üçgenin üç köşesinden karşı kenarlara (gerekirse uzantılarına) birer yükseklik çizilecektir.\n**Bu yüksekliklerle ilgili aşağıdakilerden hangisi doğrudur?**",
  gorsel: "<svg viewBox=\"0 0 340 215\" role=\"img\"><polygon points=\"196.1,112.2 40,185 300,185\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M 174.3 122.4 A 24 24 0 0 0 215.7 126\" fill=\"none\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><text x=\"196.1\" y=\"156.2\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">120°</text><text x=\"196.1\" y=\"100.2\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"28\" y=\"203\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"312\" y=\"203\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text></svg>",
  secenekler: ["Yalnızca A köşesinden çizilen yükseklik üçgenin dışına düşer.","Yalnızca B köşesinden çizilen yükseklik üçgenin dışına düşer.","Üç köşeden çizilen yüksekliklerin hepsi üçgenin içinde kalır.","B ve C köşelerinden çizilen yükseklikler üçgenin dışına düşer."],
  dogru: 3,
  hatalar: ["A'dan inen yükseklik, karşı kenar olan [BC]'nin içine düşer. Dışarı düşenler B ve C köşelerinden çizilenlerdir.","C köşesinden çizilen yükseklik de dışarı düşer; geniş açılı üçgende iki yükseklik üçgenin dışındadır.","Bu durum yalnızca dar açılı üçgende olur. Geniş açılı üçgende iki yükseklik dışarı düşer.",null],
  aciklama: "Yükseklik, köşeden karşı kenara (gerekirse uzantısına) çizilen dikmedir. Geniş açılı üçgende, geniş açının köşesi dışındaki iki köşeden inen dikmeler kenarların uzantısına düşer.\nAdım 1: A köşesinden [BC]'ye inen dikme, [BC] kenarının üzerine düşer (üçgenin içindedir).\nAdım 2: B köşesinden [AC] doğrusuna dikme inmek istersen, A açısı geniş olduğundan ayak noktası A köşesinin ötesinde, [CA]'nın uzantısında kalır; yani üçgenin dışındadır.\nAdım 3: C köşesinden [AB] doğrusuna inen dikmenin ayağı da [BA]'nın uzantısına düşer.\nSonuç: Geniş açılı üçgende B ve C'den çizilen iki yükseklik üçgenin dışındadır.\nSık yapılan hata: Yüksekliğin her zaman üçgenin içinde kaldığını sanmak.\nCevap D."
},
{
  id: "mat-uc-239",
  kazanim: "M.8.3.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Bir marangoz, uzunlukları tam sayı santimetre olan üç çubukla üçgen biçimli bir çerçeve yapacaktır. Üç çubuğun uzunlukları birbirinden farklıdır. En kısa çubuk 5 cm, en uzun çubuk 12 cm'dir.\n**Buna göre orta uzunluktaki çubuk kaç farklı değer alabilir?**",
  gorsel: null,
  secenekler: ["8","6","5","4"],
  dogru: 3,
  hatalar: ["Eşitsizliği hiç kullanmadın; 5'ten 12'ye kadar bütün tam sayıları (uçlar dahil 8 değer) saydın. Çubuklar farklı olduğundan uçlar zaten olamaz.","Üçgen eşitsizliğini kullanmadın; yalnızca farklılık koşuluyla 6, 7, 8, 9, 10, 11 değerlerini (6 değer) saydın. 5 + 6 = 11 < 12 olduğundan 6 uygun değildir.","7 cm'yi de saydın. 5 + 7 = 12 olduğundan çubuklar bir doğruya yatar, üçgen oluşmaz.",null],
  aciklama: "Üç çubuğun uzunlukları farklı olduğundan orta çubuğa b dersek 5 < b < 12 olur. Üçgen oluşması için en kısa iki kenarın toplamı en uzun kenardan büyük olmalıdır.\nAdım 1: 5 + b > 12 olmalıdır, yani b > 7.\nAdım 2: 7 < b < 12 koşulunu sağlayan tam sayılar 8, 9, 10 ve 11'dir.\nAdım 3: Toplam 4 değer vardır. b = 12 olamaz, çünkü çubukların uzunlukları birbirinden farklıdır.\nSık yapılan hata: b = 7'yi saymak (5 + 7 = 12, eşitlik üçgen vermez).\nCevap D."
},
{
  id: "mat-uc-240",
  kazanim: "M.8.3.1.4",
  kademe: 2,
  zorluk: 2,
  soru: "Ali, uzunluğu |KL| olan bir doğru parçası çizdi. Pergelini 5 cm açarak K merkezli ve L merkezli birer yay çizdi; yayların kesiştiği noktayı M olarak işaretleyip KLM üçgenini oluşturacak.\n**|KL| aşağıdakilerden hangisi olursa yaylar kesişmez ve üçgen çizilemez?**",
  gorsel: null,
  secenekler: ["12 cm","9 cm","6 cm","4 cm"],
  dogru: 0,
  hatalar: [null,"5 + 5 = 10, 9'dan büyüktür; yaylar kesişir ve kenarları 9, 5, 5 olan bir üçgen çizilir.","5 + 5 = 10, 6'dan büyüktür; yaylar kesişir ve kenarları 6, 5, 5 olan bir üçgen çizilir.","Kenarlar 4, 5, 5 olur; 5 − 5 < 4 < 5 + 5 olduğundan yaylar kesişir ve üçgen çizilir."],
  aciklama: "Pergelle çizilen iki yay, açıklık toplamı merkezler arası uzaklıktan büyükse kesişir.\nAdım 1: Üçgenin kenarları |KL|, 5 ve 5 cm olur.\nAdım 2: Üçgen eşitsizliği için |KL| < 5 + 5 = 10 olmalıdır.\nAdım 3: Seçeneklerden yalnızca 12 cm bu koşula uymaz; yaylar birbirine ulaşamaz.\nSağlama: 4, 6 ve 9 cm değerleri 10'dan küçüktür, bunlarla yaylar kesişir.\nCevap A."
},
{
  id: "mat-uc-241",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 2,
  soru: "Bir duvara dayanacak ahşap merdivenin alt ucu duvarın dibinden 0,7 m uzakta, üst ucu ise zeminden 2,4 m yüksekte olacaktır (duvar zemine diktir). Usta, merdivenin yan kirişlerini gereken boydan 0,5 m uzun keserek bağlantı payı bırakacaktır.\n**Ustanın kesmesi gereken kirişin boyu kaç metredir?**",
  gorsel: "<svg viewBox=\"0 0 330 245\" role=\"img\"><line x1=\"250\" y1=\"40\" x2=\"250\" y2=\"210\" stroke=\"currentColor\" stroke-width=\"5\"/><line x1=\"150\" y1=\"210\" x2=\"250\" y2=\"210\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"203.3\" y1=\"210\" x2=\"250\" y2=\"50\" stroke=\"var(--vurgu)\" stroke-width=\"4\"/><polyline points=\"238,210 238,198 250,198\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"227\" y=\"232\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">0,7 m</text><text x=\"262\" y=\"135\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">2,4 m</text><text x=\"216\" y=\"125\" text-anchor=\"end\" font-size=\"15\" fill=\"var(--vurgu)\">merdiven</text></svg>",
  secenekler: ["2,5","3,0","3,1","3,6"],
  dogru: 1,
  hatalar: ["Bağlantı payını (0,5 m) eklemeyi unuttun; 2,5 m merdivenin boyudur, kesilecek kirişin boyu değil.",null,"Dik kenarları topladın (0,7 + 2,4 = 3,1). Merdiven hipotenüstür; kareler toplanıp karekök alınarak bulunur.","Hem dik kenarları topladın (0,7 + 2,4 = 3,1) hem payı ekledin (3,1 + 0,5). Merdivenin boyu Pisagorla bulunmalıdır."],
  aciklama: "Duvar, zemin ve merdiven bir dik üçgen oluşturur; merdiven dik açının karşısındaki en uzun kenar olan hipotenüstür. Pisagor bağıntısı: dik kenarların kareleri toplamı hipotenüsün karesine eşittir.\nAdım 1: Merdivenin boyuna c dersek c^{2} = 0,7^{2} + 2,4^{2} = 0,49 + 5,76 = 6,25 olur.\nAdım 2: 2,5 · 2,5 = 6,25 olduğundan c = 2,5 m'dir (7-24-25 üçlüsünün 0,1 katı).\nAdım 3: Kiriş, bağlantı payıyla birlikte 2,5 + 0,5 = 3,0 m uzunluğunda kesilir.\nSık yapılan hata: Dik kenarları toplamak (0,7 + 2,4 = 3,1). Hipotenüs, dik kenarların toplamından kısadır.\nCevap B."
},
{
  id: "mat-uc-242",
  kazanim: "M.8.3.1.3",
  kademe: 2,
  zorluk: 2,
  soru: "ABC üçgeninde |AB| = |BC| ve m(BAC) = 64°'dir.\n**Buna göre bu üçgenin kenar uzunlukları arasındaki sıralama aşağıdakilerden hangisidir?**",
  gorsel: "<svg viewBox=\"0 0 340 245\" role=\"img\"><polygon points=\"90,222 170,58 250,222\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"124.6\" y1=\"137.4\" x2=\"135.4\" y2=\"142.6\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><line x1=\"215.4\" y1=\"137.4\" x2=\"204.6\" y2=\"142.6\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><text x=\"134\" y=\"214\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">64°</text><text x=\"76\" y=\"240\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"170\" y=\"46\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"264\" y=\"240\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text></svg>",
  secenekler: ["|AB| = |BC| < |AC|","|AB| = |AC| < |BC|","|AB| < |BC| < |AC|","|AC| < |AB| = |BC|"],
  dogru: 3,
  hatalar: ["[AC] kenarını en uzun yazdın. m(B) = 180° − 64° − 64° = 52° en küçük açıdır; karşısındaki [AC] en kısa kenardır.","Eşit açılar A ve C'dedir; karşılarındaki kenarlar [BC] ve [AB] eşittir. [AB] ile [AC] eşit değildir.","|AB| = |BC| bilgisini kullanmadın; üç kenarı da farklı sandın.",null],
  aciklama: "Eşit kenarların karşısındaki açılar da eşittir; büyük açının karşısında büyük kenar bulunur.\nAdım 1: |AB| = |BC| ise bu kenarların karşısındaki açılar eşittir: m(C) = m(A) = 64°.\nAdım 2: m(B) = 180° − 64° − 64° = 52° olur.\nAdım 3: En küçük açı B'dir; karşısındaki [AC] en kısa kenardır. Diğer iki kenar eşittir: |AC| < |AB| = |BC|.\nSağlama: 52° < 64° = 64° ve karşılarındaki kenarlar aynı sırada: |AC| < |BC| = |AB|.\nCevap D."
},
{
  id: "mat-uc-243",
  kazanim: "M.8.3.1.1",
  kademe: 2,
  zorluk: 2,
  soru: "Şekildeki ABC eşkenar üçgeninde [AD], A açısının; [CE], C açısının açıortayıdır (D, [BC] üzerinde; E, [AB] üzerindedir). [AD] ile [CE], F noktasında kesişmektedir.\n**m(AFC) kaç derecedir?**",
  gorsel: "<svg viewBox=\"0 0 340 262\" role=\"img\"><polygon points=\"170,39.5 60,230 280,230\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"120.2\" y1=\"137.7\" x2=\"109.8\" y2=\"131.7\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><line x1=\"170\" y1=\"224\" x2=\"170\" y2=\"236\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><line x1=\"219.8\" y1=\"137.7\" x2=\"230.2\" y2=\"131.7\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><line x1=\"170\" y1=\"39.5\" x2=\"170\" y2=\"230\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/><line x1=\"280\" y1=\"230\" x2=\"115\" y2=\"134.7\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/><path d=\"M 157 62 A 26 26 0 0 0 170 65.5\" fill=\"none\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><path d=\"M 170 73.5 A 34 34 0 0 0 187 68.9\" fill=\"none\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><path d=\"M 267 207.5 A 26 26 0 0 0 257.5 217\" fill=\"none\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><path d=\"M 250.6 213 A 34 34 0 0 0 246 230\" fill=\"none\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><text x=\"170\" y=\"29.5\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"46\" y=\"246\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"294\" y=\"246\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text><text x=\"170\" y=\"250\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">D</text><text x=\"103\" y=\"134.7\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">E</text><text x=\"162\" y=\"190.5\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">F</text></svg>",
  secenekler: ["60","90","120","150"],
  dogru: 2,
  hatalar: ["Üçgenin açısı olan 60°'yi cevap sandın. AFC, açıortayların oluşturduğu küçük üçgenin bir açısıdır.","Açıortayları yükseklik gibi düşünüp 90° yazdın. AFC açısını, AFC üçgeninin açı toplamından bulmalısın.",null,"Yalnızca bir yarım açıyı çıkardın (180° − 30° = 150°). AFC üçgeninde 30° ve 30° olmak üzere iki açı bilinir."],
  aciklama: "Açıortay, köşedeki açıyı iki eş açıya böler. Eşkenar üçgenin her açısı 60°'dir.\nAdım 1: [AD] açıortay olduğundan m(FAC) = 60° ÷ 2 = 30° olur.\nAdım 2: [CE] açıortay olduğundan m(FCA) = 60° ÷ 2 = 30° olur.\nAdım 3: AFC üçgeninde m(AFC) = 180° − 30° − 30° = 120°.\nSağlama: AFC üçgeninin açıları 30° + 30° + 120° = 180°.\nCevap C."
},
{
  id: "mat-uc-244",
  kazanim: "M.8.3.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Bir üçgenin iki kenarının uzunluğu 8 cm ve 13 cm'dir. Üçüncü kenarın uzunluğu santimetre cinsinden bir tam sayıdır.\n**Bu üçgenin çevresi aşağıdakilerden hangisi __olamaz__?**",
  gorsel: null,
  secenekler: ["42","36","30","27"],
  dogru: 0,
  hatalar: [null,"Üçüncü kenar 15 cm olursa 8, 13, 15 üçgeni oluşur ve çevre 36 cm olur.","Üçüncü kenar 9 cm olursa 8, 13, 9 üçgeni oluşur ve çevre 30 cm olur.","Üçüncü kenar 6 cm olursa 8, 13, 6 üçgeni oluşur (13 − 8 = 5 < 6) ve çevre 27 cm olur."],
  aciklama: "Üçüncü kenara x dersek 13 − 8 < x < 13 + 8, yani 5 < x < 21 olur; x tam sayı ise x = 6, 7, …, 20'dir.\nAdım 1: Çevre = 8 + 13 + x = 21 + x'tir.\nAdım 2: x en az 6, en çok 20 olabilir; çevre 27 ile 41 arasında olur (27 ve 41 dahil).\nAdım 3: Seçeneklerden 27, 30 ve 36 bu aralıktadır. 42 için x = 21 gerekir; ama 8 + 13 = 21 olduğundan çubuklar doğruya yatar, üçgen oluşmaz.\nSık yapılan hata: Sınır değeri olan x = 21'i kabul etmek.\nCevap A."
},
{
  id: "mat-uc-245",
  kazanim: "M.8.3.1.4",
  kademe: 2,
  zorluk: 2,
  soru: "Bir marangoz, 6 cm, 8 cm ve 10 cm uzunluğundaki üç çubuğu uç uçta birleştirerek üçgen biçimli bir çerçeve yapmıştır.\n**Bu çerçeve ile ilgili aşağıdakilerden hangisi doğrudur?**",
  gorsel: null,
  secenekler: ["Çubukların birleştirilme biçimine göre çerçevenin açıları değişebilir; yalnızca çevre sabit kalır.","Çubuklar nasıl birleştirilirse birleştirilsin çerçevenin açıları hiç değişmez.","Çerçevenin yalnızca bir açısı sabittir; diğer iki açı çubukların konumuna göre değişir.","Çerçevenin alanı sabit kalır; fakat açıları çubukların konumuna göre değişebilir."],
  dogru: 1,
  hatalar: ["Üç kenar uzunluğu belli olan üçgen tek türlüdür; açılar da sabittir. Açıların değişebildiği çerçeve dörtgen gibi oynak olurdu.",null,"Üç kenar belli olunca üç açının hepsi belli olur; bir açıyı sabit, ikisini değişken sanmak yanlıştır.","Alan açılara bağlıdır; açılar sabit olmasaydı alan da sabit kalmazdı. Gerçekte hem alan hem açılar sabittir."],
  aciklama: "Üç kenar uzunluğu verilen üçgen tek türlü çizilir; yani kenarlar belliyse açılar da bellidir.\nAdım 1: Çubuk uzunlukları 6, 8 ve 10 cm'dir ve 6 + 8 > 10 olduğundan üçgen oluşur.\nAdım 2: Üç kenar uzunluğu üçgeni tek türlü belirlediği için çerçeve oynamaz: açılar da alan da sabittir.\nAdım 3: Dörtgen çerçeve ise dört çubukla yapılsa bile esner; üçgen çerçeve bu yüzden sağlamdır.\nSık yapılan hata: Kenarlar sabitken açıların değişebileceğini sanmak.\nCevap B."
},
{
  id: "mat-uc-246",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 2,
  soru: "Aşağıdaki kareli haritada her karenin kenarı 200 m'yi göstermektedir. Bir koşucu, parkın A noktasından B noktasına, B'den C'ye ve C'den yeniden A'ya işaretli düz yollarla koşmaktadır.\n**Koşucu bu turda toplam kaç metre yol alır?**",
  gorsel: "<svg viewBox=\"0 0 300 245\" role=\"img\"><line x1=\"50\" y1=\"50\" x2=\"50\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.25\"/><line x1=\"100\" y1=\"50\" x2=\"100\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.25\"/><line x1=\"150\" y1=\"50\" x2=\"150\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.25\"/><line x1=\"200\" y1=\"50\" x2=\"200\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.25\"/><line x1=\"250\" y1=\"50\" x2=\"250\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.25\"/><line x1=\"50\" y1=\"50\" x2=\"250\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.25\"/><line x1=\"50\" y1=\"100\" x2=\"250\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.25\"/><line x1=\"50\" y1=\"150\" x2=\"250\" y2=\"150\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.25\"/><line x1=\"50\" y1=\"200\" x2=\"250\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.25\"/><polygon points=\"50,200 50,50 250,200\" fill=\"none\" stroke=\"var(--vurgu)\" stroke-width=\"3\" stroke-linejoin=\"round\"/><polyline points=\"50,188 62,188 62,200\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"50\" cy=\"200\" r=\"4\" fill=\"currentColor\"/><circle cx=\"50\" cy=\"50\" r=\"4\" fill=\"currentColor\"/><circle cx=\"250\" cy=\"200\" r=\"4\" fill=\"currentColor\"/><text x=\"38\" y=\"216\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"38\" y=\"48\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"262\" y=\"218\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text><text x=\"150\" y=\"238\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">1 karenin kenarı = 200 m</text></svg>",
  secenekler: ["1000","1400","2400","2800"],
  dogru: 2,
  hatalar: ["Yalnızca [BC] yolunu buldun (5 kare = 1000 m). Tur, üç kenarın toplamıdır.","İki dik kenarı topladın (3 + 4 = 7 kare = 1400 m); [BC] eğik yolunu eklemedin.",null,"Eğik yolu da dik kenarların toplamı saydın ([BC] = 3 + 4 = 7 kare); 14 kare = 2800 m buldun. Eğik yol Pisagorla bulunur."],
  aciklama: "Kareli zeminde yatay ve dikey çizgiler birbirine diktir; bu yüzden A köşesindeki açı diktir ve [BC] hipotenüstür.\nAdım 1: |AB| = 3 kare = 3 · 200 = 600 m ve |CA| = 4 kare = 4 · 200 = 800 m.\nAdım 2: Kare sayısıyla Pisagor: |BC|^{2} = 3^{2} + 4^{2} = 9 + 16 = 25 olduğundan |BC| = 5 kare = 1000 m'dir.\nAdım 3: Tur = 600 + 800 + 1000 = 2400 m.\nSağlama: 3 + 4 + 5 = 12 kare ve 12 · 200 = 2400 m.\nSık yapılan hata: Eğik yolu 3 + 4 = 7 kare saymak. Eğik yol, dik kenarların toplamından kısadır.\nCevap C."
},
{
  id: "mat-uc-247",
  kazanim: "M.8.3.1.4",
  kademe: 2,
  zorluk: 2,
  soru: "Ali, kenar uzunlukları 7 cm, 24 cm ve 25 cm olan bir üçgen çizdi. Selin de aynı üç uzunluğu kullanarak başka bir kâğıda üçgen çizdi.\n**Selin'in çizdiği üçgenin alanı kaç santimetrekaredir?**",
  gorsel: null,
  secenekler: ["300","168","87,5","84"],
  dogru: 3,
  hatalar: ["24 ile 25'i çarpıp ikiye böldün. 25 hipotenüstür, 24'e dik değildir; yükseklik olarak kullanılamaz.","Alanı bulurken ikiye bölmeyi unuttun (7 · 24 = 168).","7 ile 25'i çarpıp ikiye böldün. 25 hipotenüstür, yükseklik olamaz.",null],
  aciklama: "Üç kenar uzunluğu verilen üçgen tek türlü çizilir; Ali'nin ve Selin'in üçgenleri aynıdır.\nAdım 1: En uzun kenarın karesini kontrol et: 7^{2} + 24^{2} = 49 + 576 = 625 = 25^{2}.\nAdım 2: Pisagor bağıntısı sağlandığı için üçgen diktir; 7 ve 24 dik kenarlar, 25 hipotenüstür.\nAdım 3: Alan = dik kenarların çarpımı ÷ 2 = 7 · 24 ÷ 2 = 84 cm^{2}.\nSık yapılan hata: Hipotenüsü taban ya da yükseklik olarak kullanmak.\nCevap D."
},
{
  id: "mat-uc-248",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 2,
  soru: "Aşağıdaki koordinat düzleminde bir haritadaki iki park A(−5, 3) ve B(7, −2) noktalarıyla gösterilmiştir. Eksenlerdeki her birim gerçekte 1 km'yi göstermektedir.\n**İki park arasındaki uzaklık kaç kilometredir?**",
  gorsel: "<svg viewBox=\"0 0 370 250\" role=\"img\"><line x1=\"40\" y1=\"20\" x2=\"40\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"57\" y1=\"20\" x2=\"57\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"74\" y1=\"20\" x2=\"74\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"91\" y1=\"20\" x2=\"91\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"108\" y1=\"20\" x2=\"108\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"125\" y1=\"20\" x2=\"125\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"142\" y1=\"20\" x2=\"142\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"159\" y1=\"20\" x2=\"159\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"176\" y1=\"20\" x2=\"176\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"193\" y1=\"20\" x2=\"193\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"210\" y1=\"20\" x2=\"210\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"227\" y1=\"20\" x2=\"227\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"244\" y1=\"20\" x2=\"244\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"261\" y1=\"20\" x2=\"261\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"278\" y1=\"20\" x2=\"278\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"295\" y1=\"20\" x2=\"295\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"312\" y1=\"20\" x2=\"312\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"329\" y1=\"20\" x2=\"329\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"346\" y1=\"20\" x2=\"346\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"224\" x2=\"346\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"207\" x2=\"346\" y2=\"207\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"190\" x2=\"346\" y2=\"190\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"173\" x2=\"346\" y2=\"173\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"156\" x2=\"346\" y2=\"156\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"139\" x2=\"346\" y2=\"139\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"122\" x2=\"346\" y2=\"122\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"105\" x2=\"346\" y2=\"105\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"88\" x2=\"346\" y2=\"88\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"71\" x2=\"346\" y2=\"71\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"54\" x2=\"346\" y2=\"54\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"37\" x2=\"346\" y2=\"37\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"20\" x2=\"346\" y2=\"20\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"40\" y1=\"139\" x2=\"346\" y2=\"139\" stroke=\"currentColor\" stroke-width=\"1.8\"/><line x1=\"176\" y1=\"20\" x2=\"176\" y2=\"224\" stroke=\"currentColor\" stroke-width=\"1.8\"/><text x=\"74\" y=\"156\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">−6</text><text x=\"108\" y=\"156\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">−4</text><text x=\"142\" y=\"156\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">−2</text><text x=\"210\" y=\"156\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">2</text><text x=\"278\" y=\"156\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">6</text><text x=\"312\" y=\"156\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">8</text><text x=\"170\" y=\"42\" text-anchor=\"end\" font-size=\"14\" fill=\"currentColor\">6</text><text x=\"170\" y=\"76\" text-anchor=\"end\" font-size=\"14\" fill=\"currentColor\">4</text><text x=\"170\" y=\"110\" text-anchor=\"end\" font-size=\"14\" fill=\"currentColor\">2</text><text x=\"170\" y=\"178\" text-anchor=\"end\" font-size=\"14\" fill=\"currentColor\">−2</text><text x=\"170\" y=\"212\" text-anchor=\"end\" font-size=\"14\" fill=\"currentColor\">−4</text><line x1=\"91\" y1=\"88\" x2=\"295\" y2=\"173\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"7 4\"/><circle cx=\"91\" cy=\"88\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"295\" cy=\"173\" r=\"4.5\" fill=\"currentColor\"/><text x=\"101\" y=\"82\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">A(−5, 3)</text><text x=\"291\" y=\"197\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">B(7, −2)</text></svg>",
  secenekler: ["√{29}","7","√{119}","13"],
  dogru: 3,
  hatalar: ["Negatif koordinatta işaret hatası yaptın: yatay fark 7 − (−5) = 12 olmalıdır; 2 bulup (2^{2} + 5^{2} = 29) √{29} yazdın.","Yatay ve dikey farkları çıkardın (12 − 5 = 7). Uzaklık, bu farklarla kurulan dik üçgenin hipotenüsüdür.","Kareleri toplamak yerine çıkardın (12^{2} − 5^{2} = 119). Hipotenüsün karesi, dik kenarların karelerinin toplamıdır.",null],
  aciklama: "Koordinat düzleminde iki nokta arasındaki uzaklık, o noktalardan kurulan dik üçgenin hipotenüsüdür; yatay ve dikey fark dik kenarlardır.\nAdım 1: Yatay fark = 7 − (−5) = 12 birim.\nAdım 2: Dikey fark = 3 − (−2) = 5 birim.\nAdım 3: Uzaklığa c dersek c^{2} = 12^{2} + 5^{2} = 144 + 25 = 169 olur. 13 · 13 = 169 olduğundan c = 13 birim, yani 13 km'dir.\nSık yapılan hata: Negatif sayıları çıkarırken işareti yanlış almak (7 − (−5) = 12, 2 değil).\nCevap D."
},
{
  id: "mat-uc-249",
  kazanim: "M.8.3.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Kenar uzunlukları 6 cm, 9 cm ve (x + 2) cm olan bir üçgen çizilecektir. x bir tam sayıdır.\n**Buna göre x en çok kaç olabilir?**",
  gorsel: null,
  secenekler: ["12","13","14","15"],
  dogru: 0,
  hatalar: [null,"x + 2 = 15 olan x = 13'ü de kabul ettin. 6 + 9 = 15 olduğundan eşitlik durumunda üçgen oluşmaz.","x + 2 < 15 yazmak yerine x < 15 yazıp 2'yi unuttun. x = 14 için üçüncü kenar 16 olur ve 6 + 9 = 15 < 16'dır.","6 + 9 = 15 toplamını doğrudan x'e eşitledin. Eşitsizlikte (x + 2) ifadesi toplamdan küçük olmalıdır."],
  aciklama: "Üçgen eşitsizliğine göre üçüncü kenar, diğer iki kenarın toplamından küçük, farkından büyüktür.\nAdım 1: 9 − 6 < x + 2 < 9 + 6 yazılır: 3 < x + 2 < 15.\nAdım 2: Her taraftan 2 çıkarılır: 1 < x < 13.\nAdım 3: x tam sayı olduğundan en büyük değeri 12'dir.\nSağlama: x = 12 için kenarlar 6, 9, 14 olur ve 6 + 9 = 15 > 14 olduğundan üçgen oluşur.\nCevap A."
},
{
  id: "mat-uc-250",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 2,
  soru: "Üçgen biçimli bir parkın kenar uzunlukları 14 m, 48 m ve 50 m'dir. Parkın 14 m ve 48 m uzunluğundaki kenarları B köşesinde birleşmektedir.\n**B köşesindeki açı ile ilgili aşağıdakilerden hangisi doğrudur?**",
  gorsel: "<svg viewBox=\"0 0 230 275\" role=\"img\"><polygon points=\"50,232 106,232 106,40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"78\" y=\"256\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">14 m</text><text x=\"116\" y=\"140\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">48 m</text><text x=\"62\" y=\"130\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">50 m</text><text x=\"40\" y=\"238\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"116\" y=\"254\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"106\" y=\"28\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text></svg>",
  secenekler: ["Dar açıdır; çünkü iki kısa kenarın toplamı en uzun kenardan büyüktür.","Geniş açıdır; çünkü karşısında en uzun kenar bulunur.","Dik açıdır; çünkü kısa kenarların kareleri toplamı, en uzun kenarın karesine eşittir.","Açının türü belirlenemez; çünkü kenar uzunlukları açı hakkında bilgi vermez."],
  dogru: 2,
  hatalar: ["14 + 48 > 50 koşulu yalnızca üçgenin var olduğunu söyler, açının türünü vermez. Açının türü için karelere bakılır.","En uzun kenarın karşısındaki açı en büyük açıdır ama geniş olması gerekmez. 14^{2} + 48^{2} ile 50^{2}'yi karşılaştırmalısın.",null,"Kenar uzunlukları Pisagor bağıntısıyla karşılaştırılarak açının dik, dar ya da geniş olduğu kesin olarak belirlenir."],
  aciklama: "Pisagor bağıntısının tersi: bir üçgende en uzun kenarın karesi diğer iki kenarın kareleri toplamına eşitse, en uzun kenarın karşısındaki açı diktir. Küçükse dar, büyükse geniş açıdır.\nAdım 1: B köşesi, 50 m'lik kenarın karşısındadır. Kareleri karşılaştır: 14^{2} + 48^{2} = 196 + 2304 = 2500.\nAdım 2: 50^{2} = 2500 olduğundan 14^{2} + 48^{2} = 50^{2} eşitliği sağlanır.\nAdım 3: Bu durumda B köşesindeki açı diktir.\nSık yapılan hata: Yalnızca toplamları karşılaştırıp (14 + 48 > 50) açının türünü yorumlamak.\nCevap C."
},
{
  id: "mat-uc-251",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 2,
  soru: "Elif, gergin ve düz bir ip ile uçurtma uçuruyor. İpin boyu 37 m'dir ve ip, yerden 1 m yükseklikteki makaradan çıkmaktadır. Uçurtmanın tam altındaki zemin noktası Elif'ten 35 m uzaktadır (zemin düz ve yataydır; şekil ölçekli değildir).\n**Uçurtma yerden kaç metre yüksekliktedir?**",
  gorsel: "<svg viewBox=\"0 0 330 245\" role=\"img\"><line x1=\"30\" y1=\"200\" x2=\"300\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"60\" y1=\"200\" x2=\"60\" y2=\"184\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"60\" y1=\"184\" x2=\"255\" y2=\"184\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-dasharray=\"4 4\" stroke-opacity=\"0.7\"/><line x1=\"255\" y1=\"200\" x2=\"255\" y2=\"118\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"7 4\"/><line x1=\"60\" y1=\"184\" x2=\"255\" y2=\"118\" stroke=\"currentColor\" stroke-width=\"2.5\"/><circle cx=\"60\" cy=\"184\" r=\"3.5\" fill=\"currentColor\"/><polygon points=\"255,90 266,104 255,118 244,104\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/><polyline points=\"243,184 243,172 255,172\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"60\" y1=\"214\" x2=\"255\" y2=\"214\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"60\" y1=\"208\" x2=\"60\" y2=\"220\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"255\" y1=\"208\" x2=\"255\" y2=\"220\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"157\" y=\"236\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">35 m</text><text x=\"50\" y=\"197\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">1 m</text><text x=\"140\" y=\"140\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">37 m</text><text x=\"272\" y=\"165\" text-anchor=\"start\" font-size=\"16\" fill=\"var(--vurgu)\" font-weight=\"bold\">?</text></svg>",
  secenekler: ["√{2594}","13","12","2"],
  dogru: 1,
  hatalar: ["İpi dik kenar sandın: 37^{2} + 35^{2} = 2594 buldun. İp hipotenüstür; öbür dik kenar kareler çıkarılarak bulunur.",null,"Makaranın yerden 1 m yüksekte olduğunu unuttun. 12 m, uçurtmanın makara seviyesinden yüksekliğidir.","Hipotenüsle dik kenarı doğrudan çıkardın (37 − 35 = 2). Dik üçgende kenarlar değil, kenarların kareleri çıkarılır."],
  aciklama: "Makara, uçurtmanın altındaki zemin noktası ve uçurtma bir dik üçgen oluşturur; ip dik açının karşısındaki en uzun kenar olan hipotenüstür.\nAdım 1: Uçurtmanın makara seviyesinden yüksekliğine h dersek h^{2} + 35^{2} = 37^{2} olur.\nAdım 2: h^{2} = 1369 − 1225 = 144 bulunur; 12 · 12 = 144 olduğundan h = 12 m'dir.\nAdım 3: Makara yerden 1 m yüksekte olduğundan uçurtmanın yerden yüksekliği 12 + 1 = 13 m'dir.\nSağlama: 12^{2} + 35^{2} = 144 + 1225 = 1369 = 37^{2}.\nSık yapılan hata: Makaranın yerden yüksekliğini eklemeyi unutmak (12 m).\nCevap B."
},
{
  id: "mat-uc-252",
  kazanim: "M.8.3.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Üçgen biçimli bir çiçeklik yapılacaktır. Çiçekliğin bir kenarı 12 m'dir; diğer iki kenarının uzunlukları toplamı 20 m olup bu uzunlukların ikisi de tam sayı metredir.\n**Buna göre bu iki kenarın uzunlukları kaç farklı biçimde seçilebilir? (Kenarların sırası önemli değildir.)**",
  gorsel: null,
  secenekler: ["13","11","7","6"],
  dogru: 3,
  hatalar: ["Kenarların sırasını önemsedin ve (4, 16) sınır durumunu da kabul ettin.","Kenarların sırasını önemsedin: (5, 15) ile (15, 5) gibi çiftleri ayrı saydın.","(4, 16) durumunu da kabul ettin; 16 − 4 = 12 olduğundan 12, 4, 16 kenarlı üçgen oluşmaz.",null],
  aciklama: "Kenarlar a ve b olsun: a + b = 20. Üçgen eşitsizliğine göre |a − b| < 12 olmalıdır (a + b = 20 > 12 zaten sağlanır).\nAdım 1: a ≤ b alarak çiftleri yaz: (10, 10), (9, 11), (8, 12), (7, 13), (6, 14), (5, 15), (4, 16), …\nAdım 2: Farklar sırasıyla 0, 2, 4, 6, 8, 10, 12'dir. Fark 12'den küçük olmalıdır; fark 12 olunca çubuklar doğruya yatar.\nAdım 3: (10, 10), (9, 11), (8, 12), (7, 13), (6, 14) ve (5, 15) uygundur; 6 farklı seçim vardır.\nSık yapılan hata: Sınır durumunu (4, 16) saymak ya da (5, 15) ile (15, 5)'i ayrı saymak.\nCevap D."
},
{
  id: "mat-uc-253",
  kazanim: "M.8.3.1.1",
  kademe: 2,
  zorluk: 3,
  soru: "Şekildeki ABC dik üçgeninde m(ABC) = 90°, |AB| = 15 cm ve |BC| = 20 cm'dir. B köşesinden [AC] hipotenüsüne inen yüksekliğin ayağı H noktasıdır.\n**|BH| kaç santimetredir?**",
  gorsel: "<svg viewBox=\"0 0 300 250\" role=\"img\"><polygon points=\"70,75 70,210 250,210\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"70\" y1=\"210\" x2=\"134.8\" y2=\"123.6\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/><polyline points=\"70,198 82,198 82,210\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><polyline points=\"128.8,131.6 120.8,125.6 126.8,117.6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"60\" y=\"142\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">15 cm</text><text x=\"160\" y=\"232\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">20 cm</text><text x=\"110\" y=\"184\" text-anchor=\"start\" font-size=\"15\" fill=\"var(--vurgu)\" font-weight=\"bold\">?</text><text x=\"70\" y=\"62\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"56\" y=\"226\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"266\" y=\"226\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text><text x=\"136.6\" y=\"112.7\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">H</text></svg>",
  secenekler: ["12","12,5","15","17,5"],
  dogru: 0,
  hatalar: [null,"Yüksekliği kenarortay gibi düşünüp hipotenüsün yarısını aldın (25 ÷ 2 = 12,5). Yükseklik hipotenüse dik inen doğru parçasıdır, orta noktaya giden değil.","Dik kenarı (|AB| = 15) yükseklik sandın. Bu, B'den [AC]'ye inen dikme değil, üçgenin bir kenarıdır.","Dik kenarların ortalamasını ((15 + 20) ÷ 2) aldın; böyle bir kural yoktur."],
  aciklama: "Dik üçgende hipotenüse inen yüksekliği, alanı iki farklı yoldan yazarak bulabilirsin.\nAdım 1: Hipotenüsü Pisagorla bul: |AC|^{2} = 15^{2} + 20^{2} = 225 + 400 = 625, yani |AC| = 25 cm.\nAdım 2: Alan, dik kenarlarla: 15 · 20 ÷ 2 = 150 cm^{2}. Alan, hipotenüs ve yükseklikle: 25 · |BH| ÷ 2.\nAdım 3: 25 · |BH| ÷ 2 = 150 ise |BH| = 300 ÷ 25 = 12 cm.\nSağlama: 12 cm, dik kenarlardan (15 ve 20) kısadır; yükseklik bir dik kenardan uzun olamaz.\nCevap A."
},
{
  id: "mat-uc-254",
  kazanim: "M.8.3.1.3",
  kademe: 2,
  zorluk: 3,
  soru: "ABC üçgeninde |BC| kenarı, diğer iki kenarın her birinden daha uzundur ve m(ABC) = 50°'dir. m(BAC) derece cinsinden bir tam sayıdır.\n**Buna göre m(BAC) en az kaç derece olabilir?**",
  gorsel: null,
  secenekler: ["90","66","65","50"],
  dogru: 1,
  hatalar: ["En küçük değer yerine bir örnek değer aldın; 66° da uygundur, dolayısıyla 90° en az değer değildir.",null,"m(A) = 65° için m(C) = 65° olur; |AB| = |BC| eşitliği çıkar ve [BC] diğer iki kenardan da uzun olmaz.","Yalnızca B açısıyla kıyasladın (m(A) > 50°); C açısını unuttun."],
  aciklama: "Büyük kenarın karşısında büyük açı bulunur. [BC] en uzun kenar olduğundan karşısındaki A açısı diğer iki açıdan da büyüktür.\nAdım 1: m(A) > m(B) = 50° olmalıdır.\nAdım 2: m(C) = 180° − 50° − m(A) = 130° − m(A) olur ve m(A) > m(C) olmalıdır: m(A) > 130° − m(A), yani 2 · m(A) > 130°, m(A) > 65°.\nAdım 3: m(A) tam sayı olduğundan en küçük değer 66°'dir.\nSağlama: m(A) = 66° için m(C) = 64° olur; 66° hem 64°'den hem 50°'den büyüktür. m(A) = 65° olsaydı m(C) = 65° çıkar, |BC| = |AB| olurdu.\nCevap B."
},
{
  id: "mat-uc-255",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 3,
  soru: "Alanı 50 m^{2} olan kare biçimli bir bahçenin bir köşesinden karşı köşesine düz bir sulama borusu döşenecektir.\n**Borunun uzunluğu kaç metredir?**",
  gorsel: "<svg viewBox=\"0 0 300 225\" role=\"img\"><polygon points=\"70,30 230,30 230,190 70,190\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"70\" y1=\"190\" x2=\"230\" y2=\"30\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"7 4\"/><text x=\"175\" y=\"172\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">Alan = 50 m²</text><text x=\"116\" y=\"98\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--vurgu)\" font-weight=\"bold\">?</text></svg>",
  secenekler: ["25","10√{2}","10","5√{2}"],
  dogru: 2,
  hatalar: ["Alanın yarısını (50 ÷ 2 = 25) aldın. Köşegen alanla değil, Pisagor bağıntısıyla bulunur.","Kenarı 10 sanıp köşegeni 10√{2} yazdın; oysa kenar √{50} = 5√{2}'dir.",null,"Kenar uzunluğunu (√{50} = 5√{2}) buldun; boru köşegen boyunca döşenecek."],
  aciklama: "Karenin köşegeni, kareyi iki dik ikizkenar üçgene ayırır; köşegen bu üçgenlerin hipotenüsüdür.\nAdım 1: Kenara a dersek a^{2} = 50 olur (kare alanı).\nAdım 2: Köşegene d dersek d^{2} = a^{2} + a^{2} = 50 + 50 = 100 bulunur.\nAdım 3: 10 · 10 = 100 olduğundan d = 10 m'dir.\nSağlama: Köşegenin karesi, karenin alanının iki katıdır: 2 · 50 = 100.\nSık yapılan hata: Kenarı (5√{2}) bulup cevap saymak.\nCevap C."
},
{
  id: "mat-uc-256",
  kazanim: "M.8.3.1.4",
  kademe: 2,
  zorluk: 3,
  soru: "Zeynep, aşağıdaki beş ölçü grubunun her biriyle bir üçgen çizmeyi deneyecektir.\nGrup 1: |AB| = 5 cm, |BC| = 7 cm, |CA| = 12 cm\nGrup 2: |AB| = 6 cm, |AC| = 9 cm, m(A) = 30°\nGrup 3: |BC| = 8 cm, m(B) = 95°, m(C) = 85°\nGrup 4: |BC| = 8 cm, m(B) = 60°, m(C) = 70°\nGrup 5: m(A) = 50°, m(B) = 60°, m(C) = 70°\n**Bu gruplardan kaç tanesiyle tek bir üçgen çizilebilir?**",
  gorsel: null,
  secenekler: ["1","2","3","4"],
  dogru: 1,
  hatalar: ["Bir grubu eksik saydın. 2. gruptaki (iki kenar ve aralarındaki açı) ve 4. gruptaki (bir kenar ve iki komşu açı, 60° + 70° < 180°) ölçülerle de tek üçgen çizilir.",null,"5. grubu (üç açı) da yeterli saydın. Üç açı verilince açılar aynı kalır ama kenarlar değişebilir; tek üçgen belirlenmez.","3. grubu (95° + 85° = 180°, ışınlar paralel) ve 5. grubu (üç açı) da yeterli saydın."],
  aciklama: "Tek üçgen belirleyen bilgiler: üç kenar (üçgen eşitsizliği sağlanmalı), iki kenar ve aralarındaki açı, bir kenar ve ona komşu iki açı (toplamları 180°'den küçük olmalı).\nAdım 1: Grup 1: 5 + 7 = 12 olduğundan üçgen oluşmaz.\nAdım 2: Grup 2: iki kenar ve aralarındaki açı verilmiştir; tek üçgen çizilir.\nAdım 3: Grup 3: komşu açılar 95° + 85° = 180° eder; ışınlar paralel olur, üçgen çizilemez. Grup 5: yalnızca üç açı vardır; sonsuz çok üçgen çizilebilir.\nAdım 4: Grup 4: [BC] kenarı ve komşu açılar 60° + 70° = 130° < 180° olduğundan tek üçgen çizilir.\nSonuç: Yalnızca 2. ve 4. gruplar, yani 2 grup.\nSık yapılan hata: Üç açıyı ya da üçgen eşitsizliğini sağlamayan kenarları yeterli saymak.\nCevap B."
},
{
  id: "mat-uc-257",
  kazanim: "M.8.3.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Çevresi 22 cm olan ve üç kenarının uzunluğu da tam sayı santimetre olan, iki kenarı eşit uzunlukta bir üçgen çizilecektir.\n**Bu koşulları sağlayan kaç farklı üçgen çizilebilir? (Kenar uzunlukları aynı olan üçgenler aynı sayılır.)**",
  gorsel: null,
  secenekler: ["10","6","5","4"],
  dogru: 2,
  hatalar: ["Tek–çift ayrımını yapmadan taban için 1'den 10'a kadar bütün değerleri saydın; 2a + b = 22 olduğundan b çift olmalıdır.","b = 12 (5, 5, 12) durumunu da saydın; 5 + 5 = 10 < 12 olduğundan üçgen oluşmaz.",null,"b = 10 (6, 6, 10) durumunu eledin; oysa 6 + 6 = 12 > 10 olduğundan üçgen oluşur."],
  aciklama: "Eşit kenarlara a, tabana b dersek 2a + b = 22 olur. Üçgen oluşması için b < a + a = 2a olmalıdır.\nAdım 1: 2a + b = 22 olduğundan b çifttir: b = 2, 4, 6, 8, 10, … ve a = (22 − b) ÷ 2.\nAdım 2: b < 2a koşulu b < 22 − b, yani b < 11 demektir. Böylece b = 2, 4, 6, 8, 10 olabilir.\nAdım 3: Üçgenler (10, 10, 2), (9, 9, 4), (8, 8, 6), (7, 7, 8) ve (6, 6, 10) olur; toplam 5 üçgen.\nSağlama: En uç durum (6, 6, 10) için 6 + 6 = 12 > 10; (5, 5, 12) için 5 + 5 = 10 < 12 olduğundan olmaz.\nCevap C."
},
{
  id: "mat-uc-258",
  kazanim: "M.8.3.1.1",
  kademe: 2,
  zorluk: 3,
  soru: "Şekildeki ABC üçgeninde [BD] kenarortaydır (D, [AC] üzerindedir). |AD| = (3x − 2) cm, |DC| = (x + 6) cm, |AB| = 15 cm ve |BC| = 17 cm'dir.\n**Üçgenin çevresi kaç santimetredir?**",
  gorsel: "<svg viewBox=\"0 0 320 258\" role=\"img\"><polygon points=\"40,200 140.8,50.8 280,200\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"140.8\" y1=\"50.8\" x2=\"160\" y2=\"200\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/><line x1=\"100\" y1=\"194\" x2=\"100\" y2=\"206\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><line x1=\"220\" y1=\"194\" x2=\"220\" y2=\"206\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><text x=\"72\" y=\"122\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">15 cm</text><text x=\"228\" y=\"122\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">17 cm</text><text x=\"100\" y=\"226\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">(3x − 2) cm</text><text x=\"222\" y=\"226\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">(x + 6) cm</text><text x=\"140.8\" y=\"38\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"28\" y=\"206\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"294\" y=\"206\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text><text x=\"160\" y=\"248\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">D</text></svg>",
  secenekler: ["32","42","52","62"],
  dogru: 2,
  hatalar: ["[AC] kenarını hesaba katmadın (15 + 17 = 32).","[AC] yerine yalnızca yarısını (|AD| = 10 cm) ekledin. Kenarortay kenarı ikiye böler; [AC]'nin tamamı 20 cm'dir.",null,"|AD|'yi bir kez daha ekledin (52 + 10). Çevre yalnızca üç kenarın toplamıdır."],
  aciklama: "Kenarortay, köşeyi karşı kenarın orta noktasına birleştirir ve o kenarı iki eşit parçaya böler.\nAdım 1: [BD] kenarortay olduğundan |AD| = |DC| yazılır: 3x − 2 = x + 6.\nAdım 2: 2x = 8, x = 4 bulunur. Böylece |AD| = |DC| = 10 cm ve |AC| = 20 cm olur.\nAdım 3: Çevre = |AB| + |BC| + |AC| = 15 + 17 + 20 = 52 cm.\nSık yapılan hata: Parçayı (10 cm) bütün kenar sanmak.\nCevap C."
},
{
  id: "mat-uc-259",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 3,
  soru: "Kare biçimli bir origami kâğıdının köşegeni 12 cm'dir. Kâğıt bu köşegen boyunca kesilerek iki üçgene ayrılıyor.\n**Oluşan üçgenlerden birinin alanı kaç santimetrekaredir?**",
  gorsel: "<svg viewBox=\"0 0 300 225\" role=\"img\"><polygon points=\"70,30 230,30 230,190 70,190\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"70,190 230,190 230,30\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"70\" y1=\"190\" x2=\"230\" y2=\"30\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\"/><text x=\"126\" y=\"92\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">12 cm</text></svg>",
  secenekler: ["18","36","72","144"],
  dogru: 1,
  hatalar: ["Üçgenin alanını bir kez daha ikiye böldün (72 ÷ 4 = 18). Köşegen kareyi iki eş üçgene ayırır; bir üçgen karenin yarısıdır.",null,"Karenin alanını (72) üçgenin alanı sandın. Köşegen kareyi ikiye böldüğünden üçgenin alanı bunun yarısıdır.","Köşegenin karesini (12^{2} = 144) aldın; bu, karenin alanı değil, alanın iki katıdır."],
  aciklama: "Karenin kenarına a dersek köşegen, dik kenarları a ve a olan üçgenin hipotenüsüdür: d^{2} = a^{2} + a^{2}.\nAdım 1: 12^{2} = 2 · a^{2} olduğundan a^{2} = 144 ÷ 2 = 72 cm^{2} bulunur (karenin alanı).\nAdım 2: Köşegen kareyi iki eş dik üçgene ayırır; bir üçgenin alanı karenin yarısıdır.\nAdım 3: Üçgenin alanı = 72 ÷ 2 = 36 cm^{2}.\nSağlama: Dik kenarları a olan üçgenin alanı a · a ÷ 2 = 72 ÷ 2 = 36.\nCevap B."
},
{
  id: "mat-uc-260",
  kazanim: "M.8.3.1.3",
  kademe: 2,
  zorluk: 3,
  soru: "Şekilde D noktası [BC] üzerindedir, |AD| = |DC|, m(ABC) = 50° ve m(BAD) = 30°'dir.\n**|BD|, |DC| ve |AC| uzunlukları arasındaki sıralama aşağıdakilerden hangisidir?**",
  gorsel: "<svg viewBox=\"0 0 320 245\" role=\"img\"><polygon points=\"159.3,79.8 50,210 268.5,210\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"159.3\" y1=\"79.8\" x2=\"136.3\" y2=\"210\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/><line x1=\"153.7\" y1=\"145.9\" x2=\"141.9\" y2=\"143.8\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><line x1=\"202.4\" y1=\"204\" x2=\"202.4\" y2=\"216\" stroke=\"var(--vurgu)\" stroke-width=\"2\"/><text x=\"92\" y=\"200\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">50°</text><text x=\"129\" y=\"140\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">30°</text><text x=\"159.3\" y=\"69.8\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"38\" y=\"228\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"280.5\" y=\"228\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text><text x=\"136.3\" y=\"232\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">D</text></svg>",
  secenekler: ["|BD| < |DC| < |AC|","|DC| < |BD| < |AC|","|BD| < |AC| < |DC|","|AC| < |DC| < |BD|"],
  dogru: 0,
  hatalar: [null,"|BD|'yi |DC|'den büyük sandın. ABD üçgeninde |BD|, en küçük açı olan 30°'nin karşısındadır ve |AD| = |DC|'den kısadır.","ADC üçgeninde en büyük açı ADC (80°) olduğundan karşısındaki [AC], [DC]'den uzundur; sıralamayı ters yazdın.","Sıralamayı tamamen ters kurdun; en kısa kenar [BD], en uzun kenar [AC]'dir."],
  aciklama: "Büyük açının karşısında büyük kenar bulunur; eşit kenarların karşısındaki açılar eşittir.\nAdım 1: ADC, ABD üçgeninin dış açısıdır: m(ADC) = 50° + 30° = 80°. Buna göre m(ADB) = 100°.\nAdım 2: ABD üçgeninde açılar 30°, 50° ve 100°'dir. |BD| (30°'nin karşısı) < |AD| (50°'nin karşısı) olur.\nAdım 3: |AD| = |DC| olduğundan |BD| < |DC| yazılır.\nAdım 4: ADC üçgeninde |AD| = |DC| ise m(DAC) = m(DCA) = (180° − 80°) ÷ 2 = 50° olur. En büyük açı ADC (80°) olduğundan karşısındaki [AC] en uzundur: |DC| < |AC|.\nSonuç: |BD| < |DC| < |AC|.\nSağlama: ABC üçgeninde m(B) = m(C) = 50° ve m(A) = 30° + 50° = 80° olur; 50° + 50° + 80° = 180°.\nCevap A."
},
{
  id: "mat-uc-261",
  kazanim: "M.8.3.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Kenar uzunlukları santimetre cinsinden ardışık üç çift tam sayı olan bir üçgenin çevresi en çok 40 cm'dir.\n**Bu koşulları sağlayan kaç farklı üçgen vardır?**",
  gorsel: null,
  secenekler: ["3","4","5","6"],
  dogru: 1,
  hatalar: ["Bir durumu eksik saydın. x = 4, 6, 8, 10 için dört üçgen vardır (x = 4 için 4 + 6 > 8 olduğundan 4, 6, 8 üçgeni oluşur).",null,"x = 2 (2, 4, 6) durumunu da saydın; 2 + 4 = 6 olduğundan üçgen oluşmaz.","Hem x = 2'yi hem x = 12'yi saydın: 2, 4, 6 üçgen oluşturmaz; 12, 14, 16'nın çevresi 42 > 40'tır."],
  aciklama: "Kenarlar x, x + 2 ve x + 4 olsun (x çift). Üçgen oluşması için iki küçük kenarın toplamı büyük kenardan büyük olmalıdır.\nAdım 1: x + (x + 2) > x + 4 ise x > 2 olur; x çift olduğundan x ≥ 4.\nAdım 2: Çevre = 3x + 6 ≤ 40 ise x ≤ 11,3 olur; x çift olduğundan x ≤ 10.\nAdım 3: x = 4, 6, 8, 10 olur: (4, 6, 8), (6, 8, 10), (8, 10, 12), (10, 12, 14). Toplam 4 üçgen.\nSağlama: (10, 12, 14) üçgeninin çevresi 36 ≤ 40'tır; sonraki (12, 14, 16) üçgeninin çevresi 42 olduğundan koşulu bozar.\nCevap B."
},
{
  id: "mat-uc-262",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 3,
  soru: "Aşağıdaki koordinat düzleminde bir park, köşeleri A(−2, −2), B(6, −2) ve C(6, 4) olan üçgen biçimindedir. Eksenlerdeki her birim gerçekte 5 metreyi göstermektedir. Parkın çevresine tel örgü çekilecektir.\n**Çekilecek tel örgü kaç metredir?**",
  gorsel: "<svg viewBox=\"0 0 340 215\" role=\"img\"><line x1=\"36\" y1=\"20\" x2=\"36\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"52\" y1=\"20\" x2=\"52\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"68\" y1=\"20\" x2=\"68\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"84\" y1=\"20\" x2=\"84\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"100\" y1=\"20\" x2=\"100\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"116\" y1=\"20\" x2=\"116\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"132\" y1=\"20\" x2=\"132\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"148\" y1=\"20\" x2=\"148\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"164\" y1=\"20\" x2=\"164\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"180\" y1=\"20\" x2=\"180\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"196\" y1=\"20\" x2=\"196\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"212\" y1=\"20\" x2=\"212\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"228\" y1=\"20\" x2=\"228\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"244\" y1=\"20\" x2=\"244\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"260\" y1=\"20\" x2=\"260\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"276\" y1=\"20\" x2=\"276\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"292\" y1=\"20\" x2=\"292\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"308\" y1=\"20\" x2=\"308\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"36\" y1=\"180\" x2=\"308\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"36\" y1=\"164\" x2=\"308\" y2=\"164\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"36\" y1=\"148\" x2=\"308\" y2=\"148\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"36\" y1=\"132\" x2=\"308\" y2=\"132\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"36\" y1=\"116\" x2=\"308\" y2=\"116\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"36\" y1=\"100\" x2=\"308\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"36\" y1=\"84\" x2=\"308\" y2=\"84\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"36\" y1=\"68\" x2=\"308\" y2=\"68\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"36\" y1=\"52\" x2=\"308\" y2=\"52\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"36\" y1=\"36\" x2=\"308\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"36\" y1=\"20\" x2=\"308\" y2=\"20\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"36\" y1=\"132\" x2=\"308\" y2=\"132\" stroke=\"currentColor\" stroke-width=\"1.8\"/><line x1=\"116\" y1=\"20\" x2=\"116\" y2=\"180\" stroke=\"currentColor\" stroke-width=\"1.8\"/><text x=\"52\" y=\"149\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">−4</text><text x=\"180\" y=\"149\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">4</text><text x=\"244\" y=\"149\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">8</text><text x=\"308\" y=\"149\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">12</text><text x=\"110\" y=\"105\" text-anchor=\"end\" font-size=\"14\" fill=\"currentColor\">2</text><text x=\"110\" y=\"73\" text-anchor=\"end\" font-size=\"14\" fill=\"currentColor\">4</text><text x=\"110\" y=\"41\" text-anchor=\"end\" font-size=\"14\" fill=\"currentColor\">6</text><polygon points=\"84,164 212,164 212,68\" fill=\"none\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/><circle cx=\"84\" cy=\"164\" r=\"4\" fill=\"currentColor\"/><circle cx=\"212\" cy=\"164\" r=\"4\" fill=\"currentColor\"/><circle cx=\"212\" cy=\"68\" r=\"4\" fill=\"currentColor\"/><text x=\"84\" y=\"186\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">A(−2, −2)</text><text x=\"212\" y=\"186\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">B(6, −2)</text><text x=\"222\" y=\"62\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">C(6, 4)</text></svg>",
  secenekler: ["24","70","90","120"],
  dogru: 3,
  hatalar: ["Ölçeği (1 birim = 5 m) çarpmayı unuttun; 24 birim 120 m eder.","[AC] kenarını hesaba katmadın: (8 + 6) birim × 5 = 70 m.","[BC] kenarını hesaba katmadın: (8 + 10) birim × 5 = 90 m.",null],
  aciklama: "Koordinat düzleminde yatay ya da dikey doğru üzerindeki iki nokta arasındaki uzaklık, koordinat farkıdır; eğik kenar için dik üçgen kurulur.\nAdım 1: |AB| = 6 − (−2) = 8 birim; |BC| = 4 − (−2) = 6 birim.\nAdım 2: [AC] eğik kenardır: |AC|^{2} = 8^{2} + 6^{2} = 64 + 36 = 100, |AC| = 10 birim.\nAdım 3: Çevre = 8 + 6 + 10 = 24 birim. Her birim 5 m olduğundan 24 · 5 = 120 m.\nSık yapılan hata: Ölçekle çarpmayı unutmak ya da eğik kenarı 8 + 6 = 14 saymak.\nCevap D."
},
{
  id: "mat-uc-263",
  kazanim: "M.8.3.1.4",
  kademe: 2,
  zorluk: 3,
  soru: "Ece, KLM üçgenini çizecektir. |KL| = 12 cm, m(LKM) = 50° ve m(KLM) = (2x + 10)°'dir. x bir tam sayıdır.\n**Buna göre bu ölçülerle üçgen çizilebilmesi için x en çok kaç olabilir?**",
  gorsel: null,
  secenekler: ["59","60","64","84"],
  dogru: 0,
  hatalar: [null,"Sınırı dahil ettin: x = 60 için m(L) = 130° olur ve 50° + 130° = 180° eder; ışınlar paralel kalır, üçgen çizilemez.","2x + 10 yerine 2x'i kullandın (+10'u unuttun): 50 + 2x < 180 → x < 65 → 64.","50°'yi hiç toplamadın: 2x + 10 < 180 → x < 85 → 84."],
  aciklama: "Bir kenar ve ona komşu iki açı verilen üçgenin çizilebilmesi için komşu açıların toplamı 180°'den küçük olmalıdır.\nAdım 1: |KL| kenarına komşu açılar K ve L'dir: 50 + (2x + 10) < 180.\nAdım 2: 2x + 60 < 180 ise 2x < 120, yani x < 60.\nAdım 3: x tam sayı olduğundan en büyük değeri 59'dur.\nSağlama: x = 59 için m(L) = 128° ve 50° + 128° = 178° < 180°; x = 60 için toplam tam 180° olur.\nCevap A."
},
{
  id: "mat-uc-264",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 3,
  soru: "Aşağıdaki koordinat düzleminde bir haritadaki iki kent A(−3, 2) ve B(6, −10) noktalarıyla gösterilmiştir. Eksenlerdeki her birim gerçekte 10 km'yi göstermektedir. Bir otobüs, A kentinden B kentine düz bir yol boyunca saatte 75 km hızla gidecektir.\n**Otobüs yolculuğu kaç saatte tamamlar?**",
  gorsel: "<svg viewBox=\"0 0 330 285\" role=\"img\"><line x1=\"60\" y1=\"20\" x2=\"60\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"75\" y1=\"20\" x2=\"75\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"90\" y1=\"20\" x2=\"90\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"105\" y1=\"20\" x2=\"105\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"120\" y1=\"20\" x2=\"120\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"135\" y1=\"20\" x2=\"135\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"150\" y1=\"20\" x2=\"150\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"165\" y1=\"20\" x2=\"165\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"180\" y1=\"20\" x2=\"180\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"195\" y1=\"20\" x2=\"195\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"210\" y1=\"20\" x2=\"210\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"225\" y1=\"20\" x2=\"225\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"240\" y1=\"20\" x2=\"240\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"255\" y1=\"20\" x2=\"255\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"260\" x2=\"255\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"245\" x2=\"255\" y2=\"245\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"230\" x2=\"255\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"215\" x2=\"255\" y2=\"215\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"200\" x2=\"255\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"185\" x2=\"255\" y2=\"185\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"170\" x2=\"255\" y2=\"170\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"155\" x2=\"255\" y2=\"155\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"140\" x2=\"255\" y2=\"140\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"125\" x2=\"255\" y2=\"125\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"110\" x2=\"255\" y2=\"110\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"95\" x2=\"255\" y2=\"95\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"80\" x2=\"255\" y2=\"80\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"65\" x2=\"255\" y2=\"65\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"50\" x2=\"255\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"35\" x2=\"255\" y2=\"35\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"20\" x2=\"255\" y2=\"20\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.18\"/><line x1=\"60\" y1=\"80\" x2=\"255\" y2=\"80\" stroke=\"currentColor\" stroke-width=\"1.8\"/><line x1=\"135\" y1=\"20\" x2=\"135\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"1.8\"/><text x=\"75\" y=\"97\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">−4</text><text x=\"165\" y=\"97\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">2</text><text x=\"195\" y=\"97\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">4</text><text x=\"225\" y=\"97\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">6</text><text x=\"255\" y=\"97\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">8</text><text x=\"129\" y=\"25\" text-anchor=\"end\" font-size=\"14\" fill=\"currentColor\">4</text><text x=\"129\" y=\"55\" text-anchor=\"end\" font-size=\"14\" fill=\"currentColor\">2</text><text x=\"129\" y=\"145\" text-anchor=\"end\" font-size=\"14\" fill=\"currentColor\">−4</text><text x=\"129\" y=\"175\" text-anchor=\"end\" font-size=\"14\" fill=\"currentColor\">−6</text><text x=\"129\" y=\"205\" text-anchor=\"end\" font-size=\"14\" fill=\"currentColor\">−8</text><line x1=\"90\" y1=\"50\" x2=\"225\" y2=\"230\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"7 4\"/><circle cx=\"90\" cy=\"50\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"225\" cy=\"230\" r=\"4.5\" fill=\"currentColor\"/><text x=\"82\" y=\"44\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">A(−3, 2)</text><text x=\"235\" y=\"236\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">B(6, −10)</text></svg>",
  secenekler: ["30","2,8","2","0,2"],
  dogru: 2,
  hatalar: ["Karekök almayı unuttun: 225 sayısını ölçekle çarpıp (2250) hıza böldün. Uzaklık √{225} = 15 birimdir.","Farkları topladın (9 + 12 = 21 birim = 210 km; 210 ÷ 75 = 2,8). Uzaklık, dik üçgenin hipotenüsüdür.",null,"Ölçeği (1 birim = 10 km) çarpmayı unuttun: 15 ÷ 75 = 0,2."],
  aciklama: "Süre = yol ÷ hız. Yolu, koordinat farklarıyla kurulan dik üçgenin hipotenüsü ve ölçek yardımıyla bul.\nAdım 1: Yatay fark = 6 − (−3) = 9 birim, dikey fark = 2 − (−10) = 12 birim.\nAdım 2: Uzaklığa c dersek c^{2} = 9^{2} + 12^{2} = 81 + 144 = 225 olur; c = 15 birimdir.\nAdım 3: Her birim 10 km olduğundan yol 15 · 10 = 150 km'dir.\nAdım 4: Süre = 150 ÷ 75 = 2 saat.\nSık yapılan hata: Ölçeği çarpmayı unutmak ya da farkları toplayıp uzaklık saymak.\nCevap C."
},
{
  id: "mat-uc-265",
  kazanim: "M.8.3.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Kenar uzunlukları 6 cm, x cm ve (2x − 3) cm olan bir üçgen çizilecektir. x bir tam sayıdır.\n**Buna göre x'in alabileceği değerlerin toplamı kaçtır?**",
  gorsel: null,
  secenekler: ["42","39","33","30"],
  dogru: 3,
  hatalar: ["Hem x = 3'ü hem x = 9'u kabul ettin (30 + 3 + 9 = 42); ikisinde de eşitlik durumu oluşur ve üçgen çizilemez.","x = 9'u da kabul ettin: kenarlar 6, 9, 15 olur ve 6 + 9 = 15 olduğundan üçgen oluşmaz.","x = 3'ü de kabul ettin: kenarlar 6, 3, 3 olur ve 3 + 3 = 6 olduğundan üçgen oluşmaz.",null],
  aciklama: "Üçgen eşitsizliğine göre her kenar, diğer ikisinin toplamından küçük olmalıdır; bu üç eşitsizlik birlikte uygulanır.\nAdım 1: 6 + x > 2x − 3 ise x < 9.\nAdım 2: x + (2x − 3) > 6 ise 3x > 9, yani x > 3. (6 + (2x − 3) > x koşulu x > −3 verir; zaten sağlanır.)\nAdım 3: 3 < x < 9 olduğundan x = 4, 5, 6, 7, 8'dir.\nAdım 4: Toplam = 4 + 5 + 6 + 7 + 8 = 30.\nSağlama: x = 4 için kenarlar 6, 4, 5; x = 8 için kenarlar 6, 8, 13 olur ve 6 + 8 = 14 > 13'tür.\nCevap D."
},
{
  id: "mat-uc-266",
  kazanim: "M.8.3.1.1",
  kademe: 2,
  zorluk: 3,
  soru: "Şekildeki ABC ikizkenar üçgeninde |AB| = |AC| = 26 cm ve [AD] ⟂ [BC]'dir. |BD| = (2x − 2) cm ve |DC| = (x + 4) cm'dir.\n**Üçgenin alanı kaç santimetrekaredir?**",
  gorsel: "<svg viewBox=\"0 0 300 270\" role=\"img\"><polygon points=\"150,28 70,220 230,220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"150\" y1=\"28\" x2=\"150\" y2=\"220\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/><polyline points=\"150,208 162,208 162,220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"92\" y=\"118\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">26 cm</text><text x=\"208\" y=\"118\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">26 cm</text><text x=\"110\" y=\"254\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">(2x − 2) cm</text><text x=\"192\" y=\"254\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">(x + 4) cm</text><text x=\"150\" y=\"16\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"58\" y=\"236\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"242\" y=\"236\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text><text x=\"150\" y=\"238\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">D</text></svg>",
  secenekler: ["120","240","260","480"],
  dogru: 1,
  hatalar: ["|BD| = 10 cm'yi taban alıp 24 cm yükseklikle alanı hesapladın (10 · 24 ÷ 2). Taban, [BC]'nin tamamıdır (20 cm).",null,"Yan kenarı (26) yükseklik sayıp 20 · 26 ÷ 2 = 260 yazdın. Yükseklik [AD]'dir ve 24 cm'dir.","Taban × yükseklik çarpımını (20 · 24 = 480) ikiye bölmeyi unuttun."],
  aciklama: "İkizkenar üçgende tepeden tabana inen yükseklik aynı zamanda kenarortaydır; tabanı iki eşit parçaya böler.\nAdım 1: |BD| = |DC| olduğundan 2x − 2 = x + 4, yani x = 6 olur. |BD| = |DC| = 10 cm ve |BC| = 20 cm.\nAdım 2: ABD dik üçgeninde |AD|^{2} = 26^{2} − 10^{2} = 676 − 100 = 576 olur; |AD| = 24 cm.\nAdım 3: Alan = |BC| · |AD| ÷ 2 = 20 · 24 ÷ 2 = 240 cm^{2}.\nSağlama: 10-24-26, 5-12-13 üçlüsünün 2 katıdır.\nCevap B."
},
{
  id: "mat-uc-267",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 3,
  soru: "Hakan, her gün evinden okuluna önce kuzeye 48 m, sonra doğuya 20 m yürüyerek gidiyor ve okuldan eve aynı yoldan dönüyor (iki yön birbirine diktir). Yeni açılan düz bir patika ev ile okulu doğrudan birleştirmektedir. Hakan haftada 5 gün gidiş–dönüş yapıyor.\n**Hakan, patikayı kullanırsa bir haftada kaç metre yol kazanır?**",
  gorsel: "<svg viewBox=\"0 0 220 258\" role=\"img\"><line x1=\"50\" y1=\"225\" x2=\"50\" y2=\"47\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"50\" y1=\"47\" x2=\"124\" y2=\"47\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"50\" y1=\"225\" x2=\"124\" y2=\"47\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"7 4\"/><polyline points=\"50,59 62,59 62,47\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"50\" cy=\"225\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"124\" cy=\"47\" r=\"4.5\" fill=\"currentColor\"/><text x=\"40\" y=\"140\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">48 m</text><text x=\"87\" y=\"36\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">20 m</text><text x=\"50\" y=\"246\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">Ev</text><text x=\"134\" y=\"52\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">Okul</text><text x=\"100\" y=\"170\" text-anchor=\"start\" font-size=\"14\" fill=\"var(--vurgu)\">patika</text></svg>",
  secenekler: ["160","80","32","16"],
  dogru: 0,
  hatalar: [null,"Gidiş–dönüşü hesaba katmadın (5 · 16 = 80). Hakan her gün hem gidiyor hem dönüyor.","Yalnızca bir günün kazancını (gidiş + dönüş = 32 m) buldun; hafta için 5 ile çarpmalısın.","Yalnızca tek yönde ve tek günde kazanılan yolu buldun."],
  aciklama: "Eski yol iki dik kenarın toplamı, patika ise hipotenüstür. Kazanılan yol, bu ikisinin farkıdır.\nAdım 1: Patikaya c dersek c^{2} = 48^{2} + 20^{2} = 2304 + 400 = 2704 olur; 52 · 52 = 2704 olduğundan c = 52 m.\nAdım 2: Eski yol 48 + 20 = 68 m'dir. Bir yönde kazanç 68 − 52 = 16 m.\nAdım 3: Günde gidiş ve dönüş 2 · 16 = 32 m, haftada 5 gün: 5 · 32 = 160 m.\nSağlama: 20-48-52, 5-12-13 üçlüsünün 4 katıdır.\nCevap A."
},
{
  id: "mat-uc-268",
  kazanim: "M.8.3.1.3",
  kademe: 2,
  zorluk: 3,
  soru: "ABC üçgeninde |AB| = (x + 2) cm, |BC| = (2x − 1) cm ve |CA| = 10 cm'dir. m(A) > m(B) > m(C) olduğu biliniyor ve x bir tam sayıdır.\n**Buna göre x kaç farklı değer alabilir?**",
  gorsel: null,
  secenekler: ["4","3","2","1"],
  dogru: 2,
  hatalar: ["x = 5 ve x = 8 değerlerini de saydın. x = 5 için |BC| = 9 < |CA| olur; x = 8 için |AB| = |CA| = 10 çıkar.","x = 8'i de saydın: |AB| = |CA| = 10 olur, buna göre m(B) = m(C) çıkar; sıralama kesin olarak büyük ya da küçük değildir.",null,"Yalnızca bir değeri buldun. 2x − 1 > 10 ve x + 2 < 10 koşulları birlikte x = 6 ve x = 7'yi verir."],
  aciklama: "Büyük açının karşısında büyük kenar bulunur: A ↔ [BC], B ↔ [CA], C ↔ [AB].\nAdım 1: m(A) > m(B) > m(C) ise |BC| > |CA| > |AB| olur.\nAdım 2: |BC| > |CA| koşulu 2x − 1 > 10 verir: x > 5,5.\nAdım 3: |CA| > |AB| koşulu 10 > x + 2 verir: x < 8.\nAdım 4: 5,5 < x < 8 olduğundan x = 6 ya da 7'dir. Kenarlar (8, 11, 10) ve (9, 13, 10) olur ve üçgen eşitsizliğini de sağlar. 2 değer vardır.\nSık yapılan hata: x = 8'i saymak (|AB| = |CA| olur, kesin sıralama bozulur).\nCevap C."
},
{
  id: "mat-uc-269",
  kazanim: "M.8.3.1.4",
  kademe: 2,
  zorluk: 3,
  soru: "Bir kenarı 9 cm olan ve bu kenara komşu iki açısı 50° ve 50° olan bir üçgen çizilmiştir. Üçgenin diğer iki kenarının her birinin uzunluğu y cm'dir.\n**Buna göre y için aşağıdakilerden hangisi doğrudur?**",
  gorsel: null,
  secenekler: ["y < 4,5","9 < y < 18","y = 9","4,5 < y < 9"],
  dogru: 3,
  hatalar: ["Üçgen eşitsizliğini ters kullandın: y + y > 9 olmalıdır, yani y > 4,5.","Eşit kenarların tabandan uzun olduğunu sandın. Tepe açısı 80°, en büyük açıdır; karşısındaki 9 cm'lik taban en uzun kenardır, y < 9'dur.","Üçgeni eşkenar sandın; açılar 50°, 50° ve 80° olduğundan kenarlar eşit değildir.",null],
  aciklama: "Taban açıları 50° ve 50° olduğundan üçgen ikizkenardır; eşit kenarlar y'dir ve tepe açısı 180° − 100° = 80° olur.\nAdım 1: En büyük açı 80°'dir; karşısındaki taban (9 cm) en uzun kenardır. Bu yüzden y < 9.\nAdım 2: Üçgen eşitsizliği: y + y > 9, yani y > 4,5.\nAdım 3: İki koşul birlikte 4,5 < y < 9 verir.\nSık yapılan hata: Kolların tabandan uzun olduğunu sanmak.\nCevap D."
},
{
  id: "mat-uc-270",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 3,
  soru: "Dikdörtgen biçimli bir arsanın kenarları 21 m ve 28 m'dir. Bir elektrik firması, arsanın bir köşesinden karşı köşesine iki yolla kablo çekebilmektedir: Köşegen boyunca çekerse 1 m kablo 14 TL, arsanın iki kenarı boyunca (21 m + 28 m) çekerse 1 m kablo 9 TL tutmaktadır.\n**İki yöntemin maliyeti arasındaki fark kaç TL'dir?**",
  gorsel: "<svg viewBox=\"0 0 330 215\" role=\"img\"><polygon points=\"70,40 266,40 266,187 70,187\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"70\" y1=\"187\" x2=\"266\" y2=\"40\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"7 4\"/><text x=\"168\" y=\"28\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">28 m</text><text x=\"62\" y=\"118\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">21 m</text></svg>",
  secenekler: ["49","441","490","931"],
  dogru: 0,
  hatalar: [null,"Kenar yönteminin maliyetini (49 · 9 = 441 TL) fark sandın.","Köşegen yönteminin maliyetini (35 · 14 = 490 TL) fark sandın.","İki maliyeti topladın (441 + 490 = 931). Fark istendiği için çıkarılmalıdır."],
  aciklama: "Önce köşegenin uzunluğunu Pisagorla bul, sonra iki yöntemin maliyetini hesaplayıp farkı al.\nAdım 1: Köşegene c dersek c^{2} = 21^{2} + 28^{2} = 441 + 784 = 1225 olur; c = 35 m.\nAdım 2: Köşegen yolu: 35 · 14 = 490 TL. Kenar yolu: (21 + 28) · 9 = 49 · 9 = 441 TL.\nAdım 3: Fark = 490 − 441 = 49 TL.\nSağlama: 21-28-35, 3-4-5 üçlüsünün 7 katıdır. Kısa yol her zaman ucuz olmaz; birim fiyat da önemlidir.\nCevap A."
},
{
  id: "mat-uc-271",
  kazanim: "M.8.3.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Kenar uzunlukları tam sayı santimetre olan üçgenlerin en uzun kenarı 6 cm'dir. Eşit kenarlı üçgenler de sayılacak ve kenarların sırası önemsenmeyecektir.\n**Buna göre kaç farklı üçgen çizilebilir?**",
  gorsel: null,
  secenekler: ["21","15","12","9"],
  dogru: 2,
  hatalar: ["Üçgen eşitsizliğini hiç uygulamadın; a ≤ b ≤ 6 olan bütün 21 çifti saydın.","a + b = 6 olan üç durumu da saydın: (1, 5, 6), (2, 4, 6) ve (3, 3, 6) üçgen oluşturmaz.",null,"İki kenarı eşit olan üçgenleri saymadın; (4, 4, 6) ya da (6, 6, 6) gibi üçgenler de üçgendir."],
  aciklama: "En uzun kenar 6 olsun; diğer kenarlar a ≤ b ≤ 6 olsun. Üçgen oluşması için a + b > 6 olmalıdır.\nAdım 1: b = 4 için a = 3, 4; b = 5 için a = 2, 3, 4, 5; b = 6 için a = 1, 2, 3, 4, 5, 6 uygundur.\nAdım 2: b ≤ 3 olunca a + b ≤ 6 olduğundan üçgen oluşmaz.\nAdım 3: Üçgen sayısı 2 + 4 + 6 = 12'dir.\nSağlama: (1, 6, 6) geçerlidir (1 + 6 > 6); (3, 3, 6) geçersizdir (3 + 3 = 6).\nCevap C."
},
{
  id: "mat-uc-272",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 3,
  soru: "Bir yük gemisi limandan çıkıp önce kuzeye 35 mil, sonra doğuya 60 mil ve en son güneye 10 mil gidiyor (yönler birbirine diktir, deniz düzdür).\n**Gemi son durumda limandan kuş uçuşu kaç mil uzaktadır?**",
  gorsel: "<svg viewBox=\"0 0 380 250\" role=\"img\"><line x1=\"60\" y1=\"210\" x2=\"60\" y2=\"70\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"60\" y1=\"70\" x2=\"300\" y2=\"70\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"300\" y1=\"70\" x2=\"300\" y2=\"110\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"60\" y1=\"210\" x2=\"300\" y2=\"110\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"7 4\"/><circle cx=\"60\" cy=\"210\" r=\"4.5\" fill=\"currentColor\"/><circle cx=\"300\" cy=\"110\" r=\"4.5\" fill=\"currentColor\"/><text x=\"50\" y=\"145\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">35 mil</text><text x=\"180\" y=\"58\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">60 mil</text><text x=\"310\" y=\"95\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">10 mil</text><text x=\"60\" y=\"232\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">Liman</text><text x=\"310\" y=\"124\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">Gemi</text><text x=\"205\" y=\"180\" text-anchor=\"start\" font-size=\"15\" fill=\"var(--vurgu)\" font-weight=\"bold\">?</text></svg>",
  secenekler: ["60","65","85","105"],
  dogru: 1,
  hatalar: ["Yalnızca doğu yönündeki yer değiştirmeyi aldın; kuzey–güney yönündeki net 25 mili hesaba katmadın.",null,"60 ile 25'i topladın (60 + 25 = 85). Uzaklık, bu iki yer değiştirmenin oluşturduğu dik üçgenin hipotenüsüdür.","Bütün yolları topladın (35 + 60 + 10 = 105). Soru, geminin aldığı yolu değil limandan uzaklığı soruyor."],
  aciklama: "Önce geminin limana göre net yer değiştirmesini bul; sonra bu iki yönle bir dik üçgen kur.\nAdım 1: Kuzey–güney yönünde net yer değiştirme 35 − 10 = 25 mil (kuzeyde); doğu yönünde 60 mil.\nAdım 2: Uzaklığa c dersek c^{2} = 25^{2} + 60^{2} = 625 + 3600 = 4225 olur.\nAdım 3: 65 · 65 = 4225 olduğundan c = 65 mil.\nSağlama: 25-60-65, 5-12-13 üçlüsünün 5 katıdır.\nCevap B."
},
{
  id: "mat-uc-273",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 3,
  soru: "Dik üçgen biçimli bir ahşap panonun hipotenüsü 53 dm, bir dik kenarı 28 dm'dir.\n**Bu panonun alanı kaç desimetrekaredir?**",
  gorsel: "<svg viewBox=\"0 0 330 240\" role=\"img\"><polygon points=\"60,60 60,200 285,200\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polyline points=\"60,188 72,188 72,200\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"50\" y=\"135\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">28 dm</text><text x=\"172\" y=\"224\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--vurgu)\" font-weight=\"bold\">?</text><text x=\"192\" y=\"112\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">53 dm</text></svg>",
  secenekler: ["1484","1260","742","630"],
  dogru: 3,
  hatalar: ["Hipotenüsle dik kenarı çarpıp ikiye bölmeyi unuttun (53 · 28 = 1484).","Dik kenarları (28 ve 45) çarpıp ikiye bölmeyi unuttun (28 · 45 = 1260).","Hipotenüsü taban, 28'i yükseklik alıp ikiye böldün (53 · 28 ÷ 2 = 742). Bu iki kenar birbirine dik değildir.",null],
  aciklama: "Dik üçgenin alanı, dik kenarların çarpımının yarısıdır. Önce öbür dik kenarı Pisagorla bul.\nAdım 1: Öbür dik kenara b dersek 28^{2} + b^{2} = 53^{2} olur.\nAdım 2: b^{2} = 2809 − 784 = 2025 ve 45 · 45 = 2025 olduğundan b = 45 dm.\nAdım 3: Alan = 28 · 45 ÷ 2 = 630 dm^{2}.\nSık yapılan hata: Hipotenüsü taban ya da yükseklik olarak kullanmak.\nCevap D."
},
{
  id: "mat-uc-274",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 3,
  soru: "Şekildeki ABC üçgeninde [AD] ⟂ [BC], |AB| = 10 cm, |AC| = 17 cm ve |AD| = 8 cm'dir (D noktası [BC] üzerindedir).\n**ABC üçgeninin alanı kaç santimetrekaredir?**",
  gorsel: "<svg viewBox=\"0 0 300 262\" role=\"img\"><polygon points=\"100,140 40,220 250,220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"100\" y1=\"140\" x2=\"100\" y2=\"220\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/><polyline points=\"100,208 112,208 112,220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"52\" y=\"168\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">10 cm</text><text x=\"190\" y=\"165\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">17 cm</text><text x=\"108\" y=\"203\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">8 cm</text><text x=\"100\" y=\"128\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"28\" y=\"236\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"262\" y=\"236\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text><text x=\"100\" y=\"240\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">D</text></svg>",
  secenekler: ["84","108","120","168"],
  dogru: 0,
  hatalar: [null,"|BC| = 10 + 17 = 27 aldın (27 · 8 ÷ 2 = 108). Yan kenarların toplamı taban değildir; taban |BD| + |DC|'dir.","ADC üçgeninin alanı için ikiye bölmeyi unuttun (15 · 8 = 120); ayrıca soru bütün üçgenin alanını soruyor.","Alan formülünde ikiye bölmeyi unuttun (21 · 8 = 168)."],
  aciklama: "Yükseklik [AD], tabanı [BC]'yi iki parçaya ayırır ve iki dik üçgen oluşur. Taban, iki parçanın toplamıdır.\nAdım 1: ABD dik üçgeninde |BD|^{2} = 10^{2} − 8^{2} = 36 olur; |BD| = 6 cm.\nAdım 2: ADC dik üçgeninde |DC|^{2} = 17^{2} − 8^{2} = 289 − 64 = 225 olur; |DC| = 15 cm.\nAdım 3: |BC| = 6 + 15 = 21 cm. Alan = 21 · 8 ÷ 2 = 84 cm^{2}.\nSağlama: 6-8-10 ve 8-15-17 birer Pisagor üçlüsüdür.\nCevap A."
},
{
  id: "mat-uc-275",
  kazanim: "M.8.3.1.5",
  kademe: 2,
  zorluk: 3,
  soru: "Şekildeki ABCD dörtgeninde m(ABC) = m(ACD) = 90°, |AB| = 9 cm, |BC| = 12 cm ve |CD| = 8 cm'dir.\n**ABCD dörtgeninin çevresi kaç santimetredir?**",
  gorsel: "<svg viewBox=\"0 0 290 245\" role=\"img\"><polygon points=\"70,110 70,200 190,200 238,136\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"70\" y1=\"110\" x2=\"190\" y2=\"200\" stroke=\"var(--vurgu)\" stroke-width=\"2\" stroke-dasharray=\"6 4\"/><polyline points=\"70,188 82,188 82,200\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><polyline points=\"180.4,192.8 187.6,183.2 197.2,190.4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"60\" y=\"160\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\">9 cm</text><text x=\"130\" y=\"222\" text-anchor=\"middle\" font-size=\"15\" fill=\"currentColor\">12 cm</text><text x=\"225\" y=\"182\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\">8 cm</text><text x=\"58\" y=\"106\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">A</text><text x=\"58\" y=\"216\" text-anchor=\"end\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">B</text><text x=\"200\" y=\"220\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">C</text><text x=\"248\" y=\"132\" text-anchor=\"start\" font-size=\"15\" fill=\"currentColor\" font-weight=\"bold\">D</text></svg>",
  secenekler: ["61","46","44","29"],
  dogru: 1,
  hatalar: ["[AC] köşegenini de çevreye kattın (46 + 15 = 61). Köşegen dörtgenin içinden geçer, çevrenin parçası değildir.",null,"[AD] yerine [AC] köşegenini (15 cm) ekledin (9 + 12 + 8 + 15 = 44). [AD] ayrıca Pisagorla bulunmalıdır.","[AD] kenarını hesaba katmadın (9 + 12 + 8 = 29)."],
  aciklama: "[AC] köşegeni dörtgeni iki dik üçgene ayırır: ABC üçgeni B köşesinde, ACD üçgeni C köşesinde diktir. [AC], ilkinde hipotenüs, ikincisinde bir dik kenardır.\nAdım 1: ABC dik üçgeninde |AC|^{2} = 9^{2} + 12^{2} = 81 + 144 = 225 olur; |AC| = 15 cm.\nAdım 2: ACD dik üçgeninde dik açı C'dedir; |AD|, hipotenüstür: |AD|^{2} = 15^{2} + 8^{2} = 225 + 64 = 289 olur; |AD| = 17 cm.\nAdım 3: Çevre = 9 + 12 + 8 + 17 = 46 cm.\nSağlama: 9-12-15 ve 8-15-17 birer Pisagor üçlüsüdür.\nCevap B."
}
);
